Object.entries(PSAC_FH_STATS).forEach(([school, d]) => {
  const key = ROSTERS_LOADED[school] ? `${school}::Field Hockey` : school;
  ROSTERS_LOADED[key] = { school, sport: 'Field Hockey', gender: 'F', division: 'NCAA D2', statsLoaded: true, statsSeason: d.season, partial: !d.full, place: d.place, roster: d.roster };
});

// Descarta entradas cuyo roster no se cargó: dos entradas de básquet apuntaban a un roster
// inexistente y hacían fallar el matching de todo el deporte.
Object.keys(ROSTERS_LOADED).forEach((k) => { if (!Array.isArray(ROSTERS_LOADED[k].roster)) delete ROSTERS_LOADED[k]; });

// ROSTERS_LOADED usa la universidad como clave; si tiene rosters de más de un deporte, el segundo va como "Universidad::Deporte" y la entrada trae `school`.
function rosterSchool(key, info) { return (info && info.school) || key; }
function rosterFor(university, sport, gender) {
  for (const key of [`${university}::${sport}`, university]) {
    const e = ROSTERS_LOADED[key];
    if (e && e.sport === sport && (!e.gender || !gender || e.gender === gender)) return e;
  }
  return null;
}

// Cobertura de datos por deporte/rama (para avisar en el perfil qué hay cargado).
let _cov = null;
function sportCoverage(sport, gender) {
  if (!_cov) {
    _cov = {};
    const bump = (sp, g, k) => { const key = `${sp}|${g}`; _cov[key] = _cov[key] || { coaches: 0, rosters: 0 }; _cov[key][k]++; };
    Object.keys(COACH_CONTACTS_BY_PROGRAM).forEach((k) => { const p = k.split("|"); if (p.length >= 3) bump(p[p.length - 2], p[p.length - 1], "coaches"); });
    Object.values(ROSTERS_LOADED).forEach((v) => { if (v && v.sport) bump(v.sport, v.gender || "F", "rosters"); });
  }
  return _cov[`${sport}|${gender}`] || { coaches: 0, rosters: 0 };
}
function sportHasData(sport) { const a = sportCoverage(sport, "F"), b = sportCoverage(sport, "M"); return a.coaches + a.rosters + b.coaches + b.rosters > 0; }
function rostersForSchool(school) { return Object.entries(ROSTERS_LOADED).filter(([k, v]) => rosterSchool(k, v) === school).map(([, v]) => v); }
const ROSTER_LOADED_NAMES = new Set(Object.entries(ROSTERS_LOADED).map(([k, v]) => rosterSchool(k, v)));
const ROSTER_KIND = {};
// Por universidad + deporte y también por rama: el plantel masculino no cuenta como "roster cargado" del equipo femenino.
Object.entries(ROSTERS_LOADED).forEach(([k, v]) => { [`${rosterSchool(k, v)}|${v.sport}`, `${rosterSchool(k, v)}|${v.sport}|${v.gender || "F"}`].forEach((key) => { ROSTER_KIND[key] = v.partial ? (ROSTER_KIND[key] === "full" ? "full" : "partial") : "full"; }); });
function rosterKind(school, sport, gender) { return ROSTER_KIND[gender ? `${school}|${sport}|${gender}` : `${school}|${sport}`] || null; } // "full" | "partial" | null


