function scholarshipInfo(division, sport, gender) {
  // Headcount D1 reales (verificado): básquet (ambas ramas), fútbol americano,
  // y en la rama FEMENINA: vóley, gimnasia y tenis. Todo lo demás (incluido
  // vóley/tenis masculino) es equivalencia. Antes esto estaba mal (vóley
  // como headcount sin chequear género, y gimnasia faltaba directamente).
  const headcountAnyGender = ["Basketball", "Football"];
  const headcountWomenOnly = ["Volleyball", "Gymnastics", "Tennis"];
  if (division === "NCAA D3") return SCHOLARSHIP_RULES["NCAA D3|ninguna"];
  if (division === "NJCAA D3") return { tipo: "sin beca deportiva (regla NJCAA División III)", banda: "0% deportivo — puede haber ayuda académica o por necesidad", prob: "nula (deportiva)", pctLow: 0, pctHigh: 0 };
  if (division === "CCCAA") return { tipo: "sin beca deportiva (los junior colleges de California no las dan)", banda: "0% deportivo — puede haber ayuda académica o por necesidad", prob: "nula (deportiva)", pctLow: 0, pctHigh: 0 };
  if (division === "NCAA D1") {
    const isHeadcount = headcountAnyGender.includes(sport) || (headcountWomenOnly.includes(sport) && gender === "F");
    return isHeadcount ? SCHOLARSHIP_RULES["NCAA D1|headcount"] : SCHOLARSHIP_RULES["NCAA D1|equivalencia"];
  }
  if (division === "NCAA D2") return SCHOLARSHIP_RULES["NCAA D2|equivalencia"];
  if (division === "NAIA") return SCHOLARSHIP_RULES["NAIA|equivalencia"];
  if (division && division.startsWith("NJCAA")) return SCHOLARSHIP_RULES["NJCAA D1|equivalencia"];
  return { tipo: "no determinado", banda: "sin referencia pública cargada", prob: "desconocida" };
}

function hoursLabel(h) {
  if (h == null || h < 0 || Number.isNaN(h)) return null;
  if (h <= 24 * 7) return { text: "publicado hace menos de una semana", weight: 15 };
  if (h <= 24 * 30) return { text: "publicado hace menos de un mes", weight: 8 };
  return { text: "publicado hace más de un mes — confirmar vigencia", weight: 2 };
}

/* ---------------------------------------------------------------
   PROYECCIÓN DE VACANTES HASTA EL AÑO DE INGRESO
   Un roster es una foto de UNA temporada. Para saber qué lugar va a haber cuando la
   aspirante llegue, se proyecta cuándo termina la elegibilidad de cada jugadora y se
   compara contra las que todavía van a estar.
--------------------------------------------------------------- */
// Temporada a la que corresponden los rosters cargados (2026 = temporada 2026-27). El
// básquet está confirmado como 2026-27; para el resto se asume la misma. Si se recarga un
// roster de otra temporada, se cambia acá.
const ROSTER_BASE_SEASON = 2026;
const MONTHS_ES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];

// Primera temporada en EE.UU.: quien termina la secundaria en diciembre (cierre del ciclo
// lectivo en el hemisferio sur) entra a jugar el año siguiente; el resto, el mismo año. Los
// perfiles guardados antes de pedir el mes se calculan como diciembre.
function getEntryYear(profile) {
  const year = parseInt(profile && profile.gradYear, 10) || new Date().getFullYear();
  const month = parseInt(profile && profile.gradMonth, 10) || 12;
  return month >= 12 ? year + 1 : year;
}

function describeGraduation(profile) {
  const year = profile.gradYear;
  const month = parseInt(profile.gradMonth, 10);
  return month >= 1 && month <= 12 ? `${MONTHS_ES[month - 1]} de ${year}` : `${year}`;
}

// Año de elegibilidad de una jugadora (1 = primer año ... 5 = quinto año/graduate) a partir de
// cómo lo escribe cada roster: "Sr.", "R-Jr.", "Sr (Rs)", "4th Year", "5th Yr.", "Gr."...
// Devuelve null si el roster no trae el año.
const ELIGIBILITY_PATTERNS = [
  [5, /\b(gr|grad|graduate)\b|\bfifth\b|\b5(th)?\b/],
  [4, /\bsr\b|\bsenior\b|\b4(th)?\b/],
  [3, /\bjr\b|\bjunior\b|\b3(rd)?\b/],
  [2, /\bso\b|\bsoph(omore)?\b|\b2(nd)?\b/],
  [1, /\bfr\b|\bfresh(man)?\b|\b1(st)?\b/],
];
function eligibilityOrder(label) {
  const text = String(label || "").toLowerCase().trim();
  if (!text) return null;
  let best = null;
  for (const part of text.split("/")) {
    const hit = ELIGIBILITY_PATTERNS.find(([, re]) => re.test(part));
    if (hit && (best === null || hit[0] > best)) best = hit[0];
  }
  return best;
}

// Separa un grupo de jugadoras según si siguen en el plantel en la temporada de ingreso.
// Se asumen 4 temporadas de elegibilidad contando desde el año de clase (los años extra por
// redshirt no se pueden ver en el roster, así que la cuenta puede moverse un año).
function projectRoster(players, baseSeason, entrySeason) {
  const gone = [], stays = [], unknown = [];
  for (const p of players) {
    const order = eligibilityOrder(p.class_year);
    if (order === null) { unknown.push(p); continue; }
    const seasonsLeft = order >= 4 ? 1 : 5 - order;
    const lastSeason = baseSeason + seasonsLeft - 1;
    (lastSeason < entrySeason ? gone : stays).push({ ...p, lastSeason });
  }
  return { gone, stays, unknown };
}

// Proyección de un roster para el perfil: mismo grupo de posición que usa el matching y
// temporada de ingreso nunca anterior a la primera que el roster cargado permite proyectar.
// Temporada del plantel cargado (por defecto, la base). Un plantel de una temporada anterior se "envejece":
// los que ya terminaron su elegibilidad no cuentan como parte del equipo actual.
function rosterSeasonOf(info) { return info && Number.isInteger(info.season) ? info.season : ROSTER_BASE_SEASON; }
function rosterSeasonLabel(info) { const y = rosterSeasonOf(info); return `${y}-${String(y + 1).slice(2)}`; }
function activeRoster(info) {
  const season = rosterSeasonOf(info);
  if (season >= ROSTER_BASE_SEASON) return info.roster;
  return info.roster.filter((p) => {
    const order = eligibilityOrder(p.class_year);
    if (order === null) return true;
    const seasonsLeft = order >= 4 ? 1 : 5 - order;
    return season + seasonsLeft - 1 >= ROSTER_BASE_SEASON;
  });
}
// ¿El jugador del roster juega en el mismo grupo de posición que el perfil? En básquet se agrupa en
// perímetro (G), alas/internos (F) y pivotes (C), porque los rosters mezclan "G", "PG", "GF", "FC"...
function rosterPosMatch(sport, rosterPos, profilePos) {
  const rp = String(rosterPos || "").toUpperCase(), pp = String(profilePos || "").toUpperCase();
  if (!rp || !pp) return false;
  if (sport === "Basketball") return rp.includes(pp === "C" ? "C" : pp.includes("F") ? "F" : "G");
  return rp.includes(pp[0]);
}

function projectRosterForProfile(info, profile) {
  const roster = activeRoster(info);
  const team = roster.filter((p) => rosterPosMatch(info.sport, p.position, profile.position));
  const pool = team.length ? team : roster;
  const baseSeason = rosterSeasonOf(info);
  const requested = getEntryYear(profile);
  const entrySeason = Math.max(requested, ROSTER_BASE_SEASON + 1);
  const { gone, stays, unknown } = projectRoster(pool, baseSeason, entrySeason);
  const known = gone.length + stays.length;
  // Plantel de una temporada anterior: no trae a los que ingresaron después (que seguirían en el equipo).
  // Se estima cada camada faltante como el promedio de las que sí se ven, para no inflar la vacante.
  const missingClasses = Math.max(0, ROSTER_BASE_SEASON - baseSeason);
  const estimated = missingClasses > 0 && missingClasses < 4 ? (known * missingClasses) / (4 - missingClasses) : 0;
  return {
    pool, positionMatched: team.length > 0, baseSeason, requested, entrySeason, clamped: requested < entrySeason,
    gone, stays, unknown, known, stale: missingClasses > 0, seasonLabel: rosterSeasonLabel(info),
    openShare: known ? gone.length / (known + estimated) : null,
  };
}

// ---- Necesidades publicadas por los coaches: todas las fuentes en una sola lista ----
// FieldLevel (1.738 filas), el tablero de ofertas (2.833) y Recruiting Needs (560) se solapan. Acá
// se unen sin duplicar (misma universidad + deporte + posición + clase) y cada fila conserva lo que
// alguna fuente aporte: texto del coach, perfil del coach, link a la publicación y antigüedad.
const NEED_SPORT_ALIAS = { "Track & Field": "Track" };
const NEED_TITLE_RE = /^(.+?) needed for (\d{4})$/;
let ALL_NEEDS_CACHE = null;
let NEEDS_INDEX = null;

function needKey(university, sport, positionCode, year) { return `${university}|${sport}|${positionCode || ""}|${year || ""}`; }

// Posiciones: antes alcanzaba con que el código publicado "contuviera" la letra de la atleta, así
// que una armadora ("S") figuraba como coincidencia de "DS" (defensiva) o un "G" de "GK".
// Ahora hay que coincidir exacto o estar en el mismo grupo de equivalencias del deporte.
const POSITION_ALIASES = {
  "Field Hockey": [["M", "MF", "MID", "MIDFIELD", "MIDFIELDER"], ["F", "S", "ST", "FW", "STRIKER", "FORWARD"], ["D", "DEF", "DEFENDER"], ["GK", "G", "GOALIE", "GOALKEEPER"]],
  "Soccer": [["M", "MF", "MID", "MIDFIELDER"], ["F", "FW", "ST", "S", "STRIKER", "FORWARD"], ["D", "DEF", "DEFENDER"], ["GK", "G", "GOALIE", "GOALKEEPER"]],
  "Volleyball": [["S", "SETTER"], ["OH", "OS", "OUTSIDE"], ["MB", "MH", "MIDDLE"], ["OPP", "RS", "OP", "OPPOSITE"], ["L", "LIB", "LIBERO"], ["DS", "DEFENSIVESPECIALIST"]],
  "Basketball": [["G", "PG", "SG", "GUARD"], ["F", "SF", "PF", "FORWARD"], ["C", "CENTER"]],
};
function positionMatches(sport, needCode, profilePos) {
  const tokens = (x) => String(x || "").toUpperCase().split(/[^A-Z]+/).filter(Boolean);
  const need = tokens(needCode), mine = tokens(profilePos);
  if (!need.length || !mine.length) return false;
  if (need.some((n) => mine.includes(n))) return true;
  return (POSITION_ALIASES[sport] || []).some((g) => need.some((n) => g.includes(n)) && mine.some((m) => g.includes(m)));
}


// Traduce "F needed for 2027" a "Busca: Delantera (F) · clase 2027" según el deporte.
function needSportKey(sport) {
  const s = String(sport || "").replace(/^(Men's|Women's)\s+/i, "").trim();
  return s === "Track & Field" ? "Track" : s;
}
function needPosEs(sport, gender, text) {
  const t = String(text || "").trim();
  const m = t.match(/^(.+?)\s+needed for\s+(\d{4})$/i);
  if (!m) return t;
  const g = gender || (/^Women's/i.test(String(sport)) ? "F" : /^Men's/i.test(String(sport)) ? "M" : "F");
  const names = POSITION_NAMES[needSportKey(sport)] || {};
  const parts = m[1].split(/\s*(?:\/|,|&|\bor\b|\band\b)\s*/i).map((x) => x.trim()).filter(Boolean).map((code) => {
    const e = names[code.toUpperCase()];
    if (!e) return code;
    const n = g === "M" ? e[1] : e[0];
    return `${n.charAt(0).toUpperCase() + n.slice(1)} (${code.toUpperCase()})`;
  });
  return `Busca: ${parts.join(" / ")} · clase ${m[2]}`;
}
function needTitle(row) {
  if (row.offer_title) return row.offer_title;
  if (row.position_code && row.class_year_needed) return `${row.position_code} needed for ${row.class_year_needed}`;
  return row.class_year_needed ? `clase ${row.class_year_needed}` : "búsqueda publicada";
}

function getAllNeeds() {
  if (ALL_NEEDS_CACHE) return ALL_NEEDS_CACHE;
  const rows = [];
  const byKey = new Map(); // clave -> filas (varias si el mismo programa publica para femenino y masculino)
  const add = (row) => {
    rows.push(row);
    const key = needKey(row.university, row.sport, row.position_code, row.class_year_needed);
    const list = byKey.get(key);
    if (list) list.push(row); else byKey.set(key, [row]);
  };
  for (const r of FIELDLEVEL_NEEDS) {
    add({ ...r, offer_title: r.position_code && r.class_year_needed ? `${r.position_code} needed for ${r.class_year_needed}` : null, description: null, post_url: null });
  }
  const { posted } = getOfferIndex();
  const merge = ({ sport, gender, university, division, place, title, year, text, coachUrl, sourceUrl, hours }) => {
    if (!university || !sport) return;
    const m = NEED_TITLE_RE.exec(title || "");
    const positionCode = m ? m[1] : null;
    const classYear = parseInt(year, 10) || (m ? parseInt(m[2], 10) : null) || null;
    // Solo se considera "la misma búsqueda" si la rama no se contradice (femenino vs masculino).
    const existing = positionCode
      ? (byKey.get(needKey(university, sport, positionCode, classYear)) || []).find((c) => !c.gender || !gender || c.gender === gender)
      : null;
    if (existing) { // misma búsqueda ya cargada: se completa con lo que aporta esta fuente
      if (!existing.description && text) existing.description = text;
      if (!existing.post_url && sourceUrl) existing.post_url = sourceUrl;
      if (!existing.offer_title && title) existing.offer_title = title;
      if (!existing.coach_profile_url && coachUrl) existing.coach_profile_url = coachUrl;
      return;
    }
    add({
      sport, gender: gender || null, university, division, place, position_code: positionCode, class_year_needed: classYear,
      coach_profile_url: coachUrl || null, hours_since_posted: hours == null ? null : hours, offer_title: title || null,
      description: text || null, post_url: sourceUrl || null,
    });
  };
  for (const o of OFFERS_BOARD) {
    const pst = o[8] ? posted.get(`${o[8]}|${o[4]}`) : null;
    merge({ sport: NEED_SPORT_ALIAS[o[0]] || o[0], gender: o[1], university: o[2], division: o[5], place: o[6], title: o[4], year: o[3], text: o[7], coachUrl: o[8], sourceUrl: pst ? pst.sourceUrl : null, hours: pst ? pst.hours : null });
  }
  for (const n of RECRUITING_NEEDS_GENERAL) {
    const g = /^(Women's|Men's)\s+/.exec(n.sport || "");
    const sport = (n.sport || "").replace(/^(Women's|Men's)\s+/, "");
    merge({ sport: NEED_SPORT_ALIAS[sport] || sport, gender: g ? (g[1] === "Women's" ? "F" : "M") : null, university: n.school, division: n.division, place: n.place, title: n.position, year: null, text: n.description, coachUrl: n.coachProfileUrl, sourceUrl: n.sourceUrl, hours: offerHoursFromText(n.datePosted) });
  }
  ALL_NEEDS_CACHE = rows;
  return rows;
}

function getNeedsFor(university, sport) {
  if (!NEEDS_INDEX) {
    NEEDS_INDEX = new Map();
    for (const row of getAllNeeds()) {
      const key = `${row.university}|${row.sport}`;
      const list = NEEDS_INDEX.get(key);
      if (list) list.push(row); else NEEDS_INDEX.set(key, [row]);
    }
  }
  return NEEDS_INDEX.get(`${university}|${sport}`) || [];
}

// La búsqueda de ese programa que mejor le calza a la atleta: primero la clase más cercana a su
// ingreso, después la que coincide con su posición y, a igualdad, la que trae texto del coach.
function bestPostedNeed(university, sport, gender, profile) {
  const entry = getEntryYear(profile);
  let best = null;
  for (const row of getNeedsFor(university, sport)) {
    if (gender && row.gender && row.gender !== gender) continue;
    const year = row.class_year_needed;
    const diff = year ? Math.abs(year - entry) : 9;
    const posMatch = positionMatches(sport, row.position_code, profile.position);
    const rank = (diff <= 1 ? 1000 - diff * 300 : 0) + (posMatch ? 100 : 0) + (row.description ? 10 : 0) - Math.min(diff, 9);
    if (!best || rank > best.rank) best = { row, diff, posMatch, rank };
  }
  return best;
}

// Confianza de la vacante: dos señales independientes. Si coinciden, alta; si aparece una, media.
function vacancyConfidence(openShare, postedNear) {
  const projected = openShare !== null && openShare >= 0.4;
  if (projected && postedNear) return "alta";
  if (projected || postedNear) return "media";
  return "baja";
}

/* ---------------------------------------------------------------
   MOTOR DE MATCHING (mismo algoritmo explicado que en el análisis)
--------------------------------------------------------------- */
function matchFieldLevel(profile) {
  const results = [];
  for (const row of getAllNeeds()) {
    if (row.sport !== profile.sport) continue;
    if (row.gender && row.gender !== profile.gender) continue;

    let score = 0;
    const reasons = [];

    const cy = row.class_year_needed;
    if (cy) {
      const diff = Math.abs(cy - getEntryYear(profile));
      if (diff === 0) { score += 40; reasons.push(`El coach busca cobertura exacta para ${cy}, tu año de ingreso proyectado.`); }
      else if (diff === 1) { score += 20; reasons.push(`Busca para ${cy}, un año de diferencia con tu ingreso proyectado (${getEntryYear(profile)}) — los needs se actualizan seguido, vale la pena escribir.`); }
      else { score += 5; }
    } else { score += 10; }

    if (row.position_code && positionMatches(row.sport, row.position_code, profile.position)) {
      score += 20;
      reasons.push(`La posición publicada ("${row.position_code}") coincide con la tuya.`);
    } else if (row.position_code) {
      score += 5;
      reasons.push(`Publican necesidad en "${row.position_code}" — confirmá con el coach si tu posición también aplica.`);
    } else if (/^Recruiting/i.test(row.offer_title || "")) {
      score += 8;
      reasons.push(`El coach está reclutando a la clase de ${cy || "tu año"} sin especificar posición — confirmá con él si tu posición aplica.`);
    } else {
      score += 8;
      reasons.push(`La publicación no detalla posición — confirmá con el coach si tu posición está entre las que buscan.`);
    }
    if (row.description) reasons.push(`Lo que publicó el coach: “${row.description}”`);
    if (row.rosterhunter_breakdown) {
      reasons.push(`RosterHunter reporta ${row.rosterhunter_total} vacantes reales en el plantel para la temporada que viene, por posición: ${row.rosterhunter_breakdown}.`);
    }

    const h = hoursLabel(row.hours_since_posted);
    if (h) { score += h.weight; reasons.push(`Post ${h.text}.`); }

    const sch = scholarshipInfo(row.division, row.sport, row.gender || profile.gender);
    reasons.push(`${row.division}: ${sch.tipo}. Banda estimada de ayuda: ${sch.banda}.`);
    const covSig = coverageAdmissionSignals(row.university, row.division, row.sport, row.gender || profile.gender, profile);
    score += covSig.delta; reasons.push(...covSig.reasons);

    const eada = eadaSignals(row.university, row.sport, row.gender || profile.gender, profile);
    if (eada) { score += eada.delta; reasons.push(...eada.reasons); }
    const staffSig = staffCompatriotSignal(row.university, row.sport, row.gender || profile.gender, profile);
    if (staffSig) { score += staffSig.delta; reasons.push(staffSig.reason); }

    const acadFit = checkAcademicFit(row.university, profile.major);
    const ipedsReason = ipedsAcademicReason(row.university, acadFit, profile.major);
    if (ipedsReason) { score += ipedsReason.delta; reasons.push(ipedsReason.text); }
    if (acadFit.status === "confirmado_no") {
      score -= 30;
      reasons.push(`⚠ Filtro académico: ${row.university} no ofrece "${profile.major}" como carrera de grado según su Common Data Set. ${acadFit.cds.closest_alternative || ""}`);
    } else if (acadFit.status === "confirmado_si" && acadFit.cds) {
      score += 10;
      reasons.push(`Confirmado: ${row.university} sí ofrece "${profile.major}" (o un programa equivalente) acreditado.`);
    } else if (acadFit.status === "confirmado_si" && acadFit.scorecard) {
      score += 10;
      const sc = acadFit.scorecard;
      reasons.push(`Según College Scorecard, ${row.university} tuvo graduadas recientes en "${sc.name}"${sc.earn4 ? ` — ganancia mediana a los 4 años de egresar: USD ${sc.earn4.toLocaleString("en-US")}` : ""}.`);
    }

    results.push({
      university: row.university,
      division: row.division,
      place: row.place,
      source: row.source || "FieldLevel (necesidad publicada por el coach)",
      score: Math.max(0, Math.min(100, score)),
      reasons,
      coachContact: (coachContactFor(row.university, row.sport, row.gender || profile.gender) || {}).contactUrl || row.coach_profile_url,
      coachLabel: (coachContactFor(row.university, row.sport, row.gender || profile.gender) || {}).label || row.coach_label || "Ver perfil del coach en FieldLevel",
      coachName: (coachContactFor(row.university, row.sport, row.gender || profile.gender) || {}).name || null,
      positionCode: row.position_code || null,
      classYearNeeded: row.class_year_needed || null,
      needTitle: needTitle(row),
      needText: row.description || null,
      postUrl: row.post_url || null,
      nationalityMatch: null,
      scholarship: sch,
      academicFit: acadFit,
      noAthleticAid: eada ? eada.noAid : null,
      missing: ["nivel real del plantel no comparado (sin roster cargado para esta universidad)"],
    });
  }
  // dedupe por universidad, mejor score primero
  const seen = new Set();
  return results.sort((a, b) => b.score - a.score).filter((r) => (seen.has(r.university) ? false : (seen.add(r.university), true)));
}

function matchFromLoadedRosters(profile) {
  const results = [];

  for (const [rosterKey, info] of Object.entries(ROSTERS_LOADED)) {
    const university = rosterSchool(rosterKey, info);
    if (info.sport !== profile.sport) continue; // solo universidades con roster del MISMO deporte
    if (info.gender && info.gender !== profile.gender) continue; // y de la misma rama (femenino/masculino)
    const roster = activeRoster(info);
    const proj = projectRosterForProfile(info, profile);
    const pool = proj.pool;
    const partial = !!info.partial; // plantel parcial: solo estadísticas (sin clase, posición ni origen)

    let score = 0;
    const reasons = [];

    // --- PRIORIDAD 1: afinidad nacional (pedido explícito: pesa fuerte en el ranking) ---
    // Refinado: ya no es todo-o-nada. Suma según (a) cuántos compatriotas hay, con
    // rendimientos decrecientes, (b) si alguno juega tu misma posición (precedente
    // directamente comparable, no solo "alguien de tu país en el equipo"), y (c) si
    // alguno tiene minutos/partidos reales jugados (recluta que de verdad juega, no
    // solo reclutado y en el banco).
    // Países normalizados: "Brasil" (perfil) y "Brazil" (plantel) son el mismo país. Antes se comparaba el texto tal cual
    // y solo coincidían los países que se escriben igual en castellano y en inglés (Argentina, Chile, Uruguay...).
    const myCountryKey = mailCountryKey(profile.country);
    const compatriotas = myCountryKey && myCountryKey !== "usa" ? roster.filter((p) => mailCountryKey(p.country) === myCountryKey) : [];
    if (compatriotas.length > 0) {
      const countBonus = Math.min(compatriotas.length - 1, 3) * 3; // +0 / +3 / +6 / +9 (tope en 4+)
      const mismaPosicion = compatriotas.filter((p) => rosterPosMatch(info.sport, p.position, profile.position));
      const posicionBonus = mismaPosicion.length > 0 ? 6 : 0;
      const conMinutosReales = info.statsLoaded ? compatriotas.filter((p) => (p.games_played || 0) > 0) : [];
      const provenBonus = conMinutosReales.length > 0 ? 5 : 0;
      const total = 20 + countBonus + posicionBonus + provenBonus; // base 20-38 según señales (bajó de 28: tapaba a programas sin roster)
      score += total;

      let detalle = `hay ${compatriotas.length} jugador(a/es) de tu misma nacionalidad en el plantel real (${compatriotas.map((p) => p.player_name).join(", ")})`;
      if (mismaPosicion.length > 0) {
        detalle += mismaPosicion.length === compatriotas.length
          ? ` — en tu misma posición, precedente directamente comparable`
          : ` — ${mismaPosicion.length} de ell@s en tu misma posición, precedente directamente comparable`;
      }
      if (conMinutosReales.length > 0) detalle += `, con partidos jugados de verdad (no solo reclutado)`;
      reasons.push(`🌎 Prioridad de afinidad: ${detalle} — precedente directo de adaptación y visa.`);
    } else if (partial) {
      reasons.push("Plantel parcial: la fuente solo trae estadísticas 2025 (sin país de origen), por eso no se evalúa la afinidad nacional. No descarta nada.");
    } else {
      // Sin compatriotas, dos señales más débiles (pedido de un entrenador: el staff que ya conoce la adaptación, el idioma
      // y el papeleo de jugadores de afuera recluta con menos riesgo):
      // (1) jugadores de otros países de Latinoamérica, si la atleta es latinoamericana: 8 + 2 por cada uno extra (hasta 12),
      //     +3 si alguno juega en su posición; (2) proporción de internacionales del plantel: hasta 6 puntos.
      // Las dos suman bastante menos que un compatriota (20 a 38).
      const withCountry = roster.filter((p) => mailCountryKey(p.country));
      const regionales = myCountryKey && LATAM_COUNTRIES.has(myCountryKey) ? roster.filter((p) => LATAM_COUNTRIES.has(mailCountryKey(p.country))) : [];
      if (regionales.length > 0) {
        const regPos = regionales.some((p) => rosterPosMatch(info.sport, p.position, profile.position));
        const regBonus = 8 + Math.min(regionales.length - 1, 2) * 2 + (regPos ? 3 : 0);
        score += regBonus;
        reasons.push(`🌎 Afinidad regional: no hay jugadores de tu país, pero sí ${regionales.length} de Latinoamérica (${regionales.map((p) => `${p.player_name}${p.country ? `, ${p.country}` : ""}`).join("; ")})${regPos ? ", alguno en tu posición" : ""}. El staff ya conoce la adaptación y el papeleo de jugadores de la región.`);
      }
      const intl = withCountry.filter((p) => mailCountryKey(p.country) !== "usa");
      if (myCountryKey && myCountryKey !== "usa" && withCountry.length >= 5 && intl.length > 0) {
        const share = intl.length / withCountry.length;
        const intlBonus = Math.min(6, Math.round(share * 20));
        if (intlBonus > 0) {
          score += intlBonus;
          reasons.push(`Plantel con ${intl.length} internacionales de ${withCountry.length} (${Math.round(share * 100)}%): el staff ya tramita visas y convalidaciones de estudios.`);
        }
      }
      if (regionales.length === 0) reasons.push(`Sin compatriotas confirmados en este roster (no descarta nada, solo no suma el bonus de afinidad).`);
    }

    // --- Vacante proyectada al año de ingreso ---
    const baseLabel = `${proj.baseSeason}-${String(proj.baseSeason + 1).slice(2)}`;
    const entryLabel = `${proj.entrySeason}-${String(proj.entrySeason + 1).slice(2)}`;
    const posLabel = proj.positionMatched ? "tu posición" : "todo el plantel (el roster no trae jugadoras en tu posición)";
    const need = bestPostedNeed(university, info.sport, info.gender || profile.gender, profile);
    const postedExact = !!need && need.diff === 0;
    const postedNear = !!need && need.diff <= 1;
    const confidence = vacancyConfidence(proj.openShare, postedNear);

    score += proj.openShare === null ? 5 : 5 + Math.round(20 * proj.openShare);
    if (postedExact) score += 8; else if (postedNear) score += 4;
    if (postedNear && need.posMatch) score += 6;

    if (proj.known > 0) {
      const stayText = proj.stays.length > 0
        ? ` Seguirían: ${proj.stays.slice(0, 4).map((p) => `${p.player_name} (${p.class_year}${info.statsLoaded && p.goals != null ? `, ${p.goals}/${p.assists}` : ""})`).join(", ")}${proj.stays.length > 4 ? " y otras" : ""}.`
        : " No seguiría nadie de ese grupo: el lugar se renueva por completo.";
      const clampText = proj.clamped ? ` (tu ingreso, ${proj.requested}, es anterior a lo que el plantel cargado permite proyectar; proyectamos desde ${proj.entrySeason})` : "";
      reasons.push(`Proyección a tu ingreso (temporada ${entryLabel}${clampText}): de ${proj.known} jugador(a/es) en ${posLabel} del plantel ${baseLabel}, ${proj.gone.length} ya no estarían (terminan su elegibilidad antes) y ${proj.stays.length} seguirían.${stayText}`);
    } else if (partial) {
      reasons.push("Plantel parcial: falta el año de clase y la posición, por eso no se proyecta la vacante. Se completa al cargar el plantel del equipo.");
    } else {
      reasons.push(`No se pudo proyectar la vacante: el roster no trae el año de clase de las jugadoras en ${posLabel}.`);
    }
    if (proj.stale) reasons.push(`El plantel cargado es de la temporada ${proj.seasonLabel} (el último que tenemos): ya se descontaron los que terminaron su elegibilidad, pero faltan los ingresantes posteriores y puede haber transferencias. La proyección es aproximada.`);
    if (proj.unknown.length > 0 && !partial) reasons.push(`${proj.unknown.length} jugador(a/es) sin año de clase en el roster no entran en la proyección.`);
    if (proj.known > 0 && proj.entrySeason - proj.baseSeason >= 3) reasons.push(`Tu ingreso está a ${proj.entrySeason - proj.baseSeason} temporadas del plantel cargado: para entonces se renueva casi todo el plantel actual, así que la proyección pesa menos y lo que más informa es si el coach publica búsquedas para tu clase.`);
    if (need && postedNear) {
      const yearText = postedExact ? " para la clase de tu ingreso" : `, clase ${need.row.class_year_needed}, un año de diferencia con tu ingreso (${proj.entrySeason})`;
      reasons.push(`El coach publicó una búsqueda (“${needTitle(need.row)}”)${yearText}${need.posMatch ? " y coincide con tu posición" : ""}.${need.row.description ? ` Lo que dice: “${need.row.description}”` : ""}`);
    } else if (need && need.row.class_year_needed) {
      reasons.push(`Este coach publicó búsquedas para la clase de ${need.row.class_year_needed}, lejos de tu ingreso (${proj.entrySeason}); la proyección es solo estructural.`);
    } else {
      reasons.push(`No encontramos una búsqueda publicada por este coach para tu clase (${proj.entrySeason}); la proyección es solo estructural.`);
    }

    // --- Nivel vs. plantel (solo si hay stats reales cargadas) ---
    if (isGoalkeeper(profile)) {
      score += 8;
      reasons.push("Sos arquero: el roster trae goles y asistencias, que no miden a un arquero, así que no comparamos tu nivel con el plantel. Tus atajadas y vallas invictas van en el mail.");
    } else if (info.statsLoaded) {
      // Solo cuentan las jugadoras con estadística cargada: null = sin dato (ingresantes u otras), no es un 0.
      // En un plantel parcial no hay posición: se compara contra sus 8 máximos productores, no contra todo el plantel.
      const statPool = partial ? [...roster].sort((x, y) => (y.points || 0) - (x.points || 0)).slice(0, 8) : pool;
      const withData = statPool.filter((p) => p.goals != null);
      if (withData.length >= 3) {
        const avgGoals = withData.reduce((s, p) => s + p.goals, 0) / withData.length;
        const avgAssists = withData.reduce((s, p) => s + (p.assists || 0), 0) / withData.length;
        const seasonNote = info.statsSeason ? ` de la temporada ${info.statsSeason}` : "";
        const where = partial ? `de sus 8 máximos productores${seasonNote} (el plantel parcial no trae posición)` : `real del plantel${seasonNote} en tu posición`;
        if (profile.goals >= avgGoals && profile.assists >= avgAssists) {
          score += 25;
          reasons.push(`Tu producción (${profile.goals}/${profile.assists}) está en línea o por encima del promedio ${partial ? where : where} (${avgGoals.toFixed(1)}/${avgAssists.toFixed(1)}).`);
        } else {
          score += 8;
          reasons.push(`Tu producción (${profile.goals}/${profile.assists}) está por debajo del promedio ${where} (${avgGoals.toFixed(1)}/${avgAssists.toFixed(1)}) — realista como profundidad de plantel.`);
        }
        const goneData = proj.gone.filter((p) => p.goals != null);
        if (goneData.length > 0) {
          const goneGoals = goneData.reduce((s, p) => s + p.goals, 0) / goneData.length;
          const goneAssists = goneData.reduce((s, p) => s + (p.assists || 0), 0) / goneData.length;
          reasons.push(`Las ${goneData.length} que terminan antes de tu ingreso y tienen estadística promedian ${goneGoals.toFixed(1)}/${goneAssists.toFixed(1)}: ese es el nivel que el coach tiene que reemplazar.`);
        }
      } else {
        reasons.push(`Solo ${withData.length} de ${statPool.length} jugador(a/es) de tu posición tienen estadística cargada: no alcanza para comparar tu nivel.`);
      }
    } else {
      reasons.push(`Sin estadísticas de temporada cargadas todavía para esta universidad — no se pudo comparar tu nivel real (el roster sí es real, las stats faltan).`);
    }

    const sch = scholarshipInfo(info.division, info.sport, profile.gender);
    reasons.push(`${info.division} ${info.sport}: ${sch.tipo}. Banda estimada: ${sch.banda}.`);
    const covSig = coverageAdmissionSignals(university, info.division, info.sport, info.gender || profile.gender, profile);
    score += covSig.delta; reasons.push(...covSig.reasons);

    const eada = eadaSignals(university, info.sport, info.gender || profile.gender, profile);
    if (eada) { score += eada.delta; reasons.push(...eada.reasons); }
    const staffSig = staffCompatriotSignal(university, info.sport, info.gender || profile.gender, profile);
    if (staffSig) { score += staffSig.delta; reasons.push(staffSig.reason); }

    const acadFit = checkAcademicFit(university, profile.major);
    const ipedsReason = ipedsAcademicReason(university, acadFit, profile.major);
    if (ipedsReason) { score += ipedsReason.delta; reasons.push(ipedsReason.text); }
    const missing = ["compromisos ya firmados de las clases intermedias, que ocupan parte de esas vacantes (no son públicos)"];
    if (partial) missing.unshift("el plantel completo de este equipo (año de clase, posición y ciudad de origen)");
    if (acadFit.status === "confirmado_no") {
      score -= 30;
      reasons.push(`⚠ Filtro académico (Common Data Set / fuente oficial real): NO ofrece "${profile.major}". ${acadFit.cds.closest_alternative || ""}`);
    } else if (acadFit.status === "confirmado_si" && acadFit.cds) {
      score += 10;
      reasons.push(`Confirmado por fuente oficial: ${university} sí ofrece "${profile.major}"${acadFit.cds.chembe_note ? ". " + acadFit.cds.chembe_note : "."}`);
    } else if (acadFit.status === "confirmado_si" && acadFit.scorecard) {
      score += 10;
      const sc = acadFit.scorecard;
      reasons.push(`Según College Scorecard, ${university} tuvo graduadas recientes en "${sc.name}"${sc.earn4 ? ` — ganancia mediana a los 4 años de egresar: USD ${sc.earn4.toLocaleString("en-US")}` : ""}.`);
    }
    if (acadFit.cds) {
      const coa = acadFit.cds.cost_of_attendance_usd;
      reasons.push(`${acadFit.cds.need_policy || ""} ${coa ? `Costo de asistencia de referencia: USD ${coa.toLocaleString("en")}/año.` : ""}`.trim());
    }

    const contact = coachContactFor(university, info.sport, info.gender || profile.gender) || {};
    results.push({
      university,
      division: info.division,
      place: info.place,
      source: partial ? "Estadísticas 2025 (plantel parcial: sin clase ni posición)" : postedNear ? "Roster real + búsqueda publicada por el coach" : "Roster real (inferido — sin necesidad pública equivalente confirmada)",
      score: Math.max(0, Math.min(100, score)),
      reasons,
      coachContact: contact.contactUrl || (need && need.row.coach_profile_url) || null,
      coachLabel: contact.label || (!contact.contactUrl && need && need.row.coach_profile_url ? "Ver perfil del coach en FieldLevel" : null),
      coachName: contact.name || null,
      coachTitle: contact.title || null,
      coachPhone: contact.phone || null,
      nationalityMatch: compatriotas.length > 0,
      partialRoster: partial,
      vacancy: partial ? null : { confidence, baseSeason: proj.baseSeason, entrySeason: proj.entrySeason, known: proj.known, gone: proj.gone.length, stays: proj.stays.length, unknown: proj.unknown.length, postedExact, postedNear },
      needTitle: need && postedNear ? needTitle(need.row) : null,
      needText: need && postedNear ? (need.row.description || null) : null,
      postUrl: need && postedNear ? (need.row.post_url || null) : null,
      scholarship: sch,
      academicFit: acadFit,
      noAthleticAid: eada ? eada.noAid : null,
      missing,
    });
  }

  return results;
}

// Topes de realismo: una opción imposible no puede quedar arriba solo porque tiene roster, búsqueda o compatriotas.
// Se aplican después de sumar todo: admisión muy baja, carrera que no se dicta o un faltante grande de plata.
function applyRealismCaps(r, profile) {
  let sig = null;
  try { sig = coverageAdmissionSignals(r.university, r.division, profile.sport, profile.gender, profile); } catch (e) { return r; }
  let cap = 100;
  const why = [];
  if (sig.adm.level === "muy baja") { cap = Math.min(cap, 40); why.push("la admisión es muy difícil con tu promedio"); }
  else if (sig.adm.level === "baja") { cap = Math.min(cap, 55); why.push("la admisión es difícil con tu promedio"); }
  if (r.academicFit && (r.academicFit.status === "confirmado_no" || r.academicFit.status === "ipeds_no")) { cap = Math.min(cap, 35); why.push("no dicta tu carrera"); }
  if (sig.cov.status === "falta" && sig.cov.gap > 15000) { cap = Math.min(cap, 45); why.push(`te faltarían más de USD 15.000 por año`); }
  if (r.score > cap) return { ...r, score: cap, reasons: [...r.reasons, `Tope de realismo: ${why.join(" y ")}, así que el puntaje queda en ${cap} aunque el resto sume más.`] };
  return r;
}

function runMatch(profile) {
  const a = matchFieldLevel(profile);
  const b = matchFromLoadedRosters(profile);
  // Si una universidad tiene roster cargado y además búsqueda publicada, queda una sola tarjeta:
  // la del roster, que ya incorpora la búsqueda (clase, posición y texto del coach).
  const withRoster = new Set(b.map((r) => r.university));
  return [...b, ...a.filter((r) => !withRoster.has(r.university))].map((r) => applyRealismCaps(r, profile)).sort((x, y) => y.score - x.score).slice(0, 10);
}

