function useEligibilityChecklist(division) {
  const [checked, setChecked] = useState({});
  useEffect(() => {
    try {
      const saved = JSON.parse(localStorage.getItem("rr_eligibility_checklist") || "{}");
      setChecked(saved);
    } catch (e) { /* localStorage puede fallar en modo privado */ }
  }, []);
  const toggle = (id) => {
    setChecked((prev) => {
      const next = { ...prev, [id]: !prev[id] };
      try { lsSetSynced("rr_eligibility_checklist", JSON.stringify(next)); } catch (e) {}
      return next;
    });
  };
  return [checked, toggle];
}

// ---- Hoja de ruta ----
// Esta página es la única que combina señales reales de todo el sitio (perfil cargado,
// emails de outreach generados, checklist de elegibilidad empezado)
// con pasos manuales que Smartrecruit no puede detectar solo (registro oficial NCAA,
// visitas a camps, seguimiento a coaches). El objetivo es que sea la página que el
// atleta reabre cada semana para saber exactamente qué le falta — no una lista de links.

// ---- Cuentas y sincronización (Supabase) ----
// Todo el sitio sigue funcionando 100% con localStorage si no hay sesión o si falla la red — esto es una capa
// encima, nunca un reemplazo. Un solo campo JSON por usuario (más simple de migrar que columnas sueltas).
const SUPABASE_URL = "https://dliayalkzvaugukhxmcb.supabase.co";
const SUPABASE_ANON_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRsaWF5YWxrenZhdWd1a2h4bWNiIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzI1MzkwOTMsImV4cCI6MjA4ODExNTA5M30.vGBprr8FKBxTayS6Q6ZbWIxUZKItY4avgMJbUGgQC1E";
const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
const SYNC_KEYS = ["rr_profile", "rr_favorites", "rr_outreach_log", "rr_outreach_count", "rr_eligibility_checklist", "rr_coach_emails", "rr_exam_best", "rr_checkins", "rr_admissions", "rr_roadmap_manual", "rr_visit_days", "rr_email_lang", "rr_onboarding_dismissed", "rr_mail_facts"];
function snapshotLocal() {
  const out = {};
  for (const k of SYNC_KEYS) { const v = localStorage.getItem(k); if (v != null) out[k] = v; }
  return out;
}
function restoreLocal(data) {
  if (!data) return;
  // Solo pisa las claves que la nube trae; lo que solo existe en este navegador se conserva.
  for (const k of SYNC_KEYS) { if (typeof data[k] === "string") localStorage.setItem(k, data[k]); }
}
let syncUserId = null; // seteado por App al iniciar/cerrar sesión — writeJSON lo lee para saber si hay que sincronizar
let syncTimer = null;
function scheduleSync() {
  if (!syncUserId) return;
  clearTimeout(syncTimer);
  syncTimer = setTimeout(() => {
    supabase.from("user_profiles").upsert({ id: syncUserId, data: snapshotLocal(), updated_at: new Date().toISOString() }).then(
      ({ error }) => { try { if (error) localStorage.setItem("rr_sync_pending", "1"); else localStorage.removeItem("rr_sync_pending"); } catch (e) {} },
      () => { try { localStorage.setItem("rr_sync_pending", "1"); } catch (e) {} });
  }, 1500); // debounce: espera una pausa antes de subir, para no pegarle a la red en cada tecla
}
if (typeof window !== "undefined") {
  window.addEventListener("online", () => { try { if (localStorage.getItem("rr_sync_pending")) scheduleSync(); } catch (e) {} });
}
// Copia de seguridad en archivo: funciona sin cuenta y sin conexión, y permite pasar los datos a otro celular.
function exportBackup() {
  const payload = { app: "smartrecruit", version: 1, exported_at: new Date().toISOString(), data: snapshotLocal() };
  const url = URL.createObjectURL(new Blob([JSON.stringify(payload)], { type: "application/json" }));
  const a = document.createElement("a");
  a.href = url; a.download = `smartrecruit-copia-${todayKey()}.json`; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
async function importBackup(file) {
  const text = await file.text();
  const parsed = JSON.parse(text);
  if (!parsed || parsed.app !== "smartrecruit" || !parsed.data || typeof parsed.data !== "object") throw new Error("archivo no válido");
  const safe = {};
  for (const k of SYNC_KEYS) { if (typeof parsed.data[k] === "string") safe[k] = parsed.data[k]; }
  if (!Object.keys(safe).length) throw new Error("copia vacía");
  restoreLocal(safe);
  return Object.keys(safe).length;
}
function BackupBox() {
  const [msg, setMsg] = useState("");
  const onFile = async (e) => {
    const f = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!f) return;
    try { const n = await importBackup(f); setMsg(`Copia restaurada (${n} datos). Recargando…`); setTimeout(() => window.location.reload(), 800); }
    catch (err) { setMsg("No pudimos leer ese archivo. Usá una copia exportada desde esta página."); }
  };
  return (
    <div className="rm-today-backup">
      <button className="rm-btn-inline" onClick={exportBackup}>💾 Guardar copia de mis datos</button>
      <label className="rm-btn-inline" style={{ marginLeft: 14, cursor: "pointer" }}>
        Restaurar una copia
        <input type="file" accept="application/json,.json" onChange={onFile} style={{ display: "none" }} />
      </label>
      {msg && <div className="rm-today-note" style={{ marginTop: 6 }}>{msg}</div>}
    </div>
  );
}
async function pullFromCloud(userId) {
  try {
    const { data, error } = await supabase.from("user_profiles").select("data").eq("id", userId).maybeSingle();
    if (error || !data) return false;
    const before = snapshotLocal();
    if (Object.keys(before).length) {
      try { localStorage.setItem("rr_backup_antes_de_login", JSON.stringify({ at: new Date().toISOString(), data: before })); } catch (e) {}
    }
    restoreLocal(data.data); return true;
  } catch (e) { return false; }
}
async function pushInitialSnapshot(userId) {
  try { await supabase.from("user_profiles").upsert({ id: userId, data: snapshotLocal(), updated_at: new Date().toISOString() }); } catch (e) {}
}

function readJSON(key, fallback) {
  try { return JSON.parse(localStorage.getItem(key) || "null") ?? fallback; } catch (e) { return fallback; }
}
