// Carga un <script> externo una sola vez (cachea la promesa para no duplicar tags
// si el usuario reintenta). Usado para traer Tesseract.js y pdf.js recién cuando
// hacen falta, no en el bundle principal — así no engordamos la carga inicial del sitio.
const _scriptCache = {};
function loadScriptOnce(src) {
  if (_scriptCache[src]) return _scriptCache[src];
  _scriptCache[src] = new Promise((resolve, reject) => {
    const el = document.createElement("script");
    el.src = src;
    el.onload = () => resolve();
    el.onerror = () => reject(new Error(`No se pudo cargar ${src}`));
    document.head.appendChild(el);
  });
  return _scriptCache[src];
}

// Busca en el texto crudo del OCR un número que parezca el promedio general.
// Prioriza líneas con "promedio"/"average"/"gpa"; si no encuentra, se queda con
// el número decimal más plausible (entre 0 y 100) que haya en todo el texto.
function guessGpaFromText(text) {
  const lines = text.split("\n");
  const kw = /(promedio|average|gpa|overall)/i;
  const numRe = /(\d{1,3}[.,]\d{1,2})/;
  for (const line of lines) {
    if (kw.test(line)) {
      const m = line.match(numRe);
      if (m) return m[1].replace(",", ".");
    }
  }
  const all = [...text.matchAll(/(\d{1,3}[.,]\d{1,2})/g)].map((m) => parseFloat(m[1].replace(",", ".")));
  const plausible = all.filter((n) => n > 0 && n <= 100);
  if (!plausible.length) return null;
  // el promedio de notas suele repetirse menos que fechas/folios; nos quedamos
  // con el que esté en un rango típico de nota (4 a 10, o 40 a 100) primero.
  const typical = plausible.find((n) => (n >= 4 && n <= 10) || (n >= 40 && n <= 100));
  return String(typical ?? plausible[0]);
}

function GpaFileReader({ onExtracted }) {
  const [status, setStatus] = useState("idle"); // idle | loading | done | error
  const [statusMsg, setStatusMsg] = useState("");
  const [rawText, setRawText] = useState("");

  async function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setStatus("loading");
    setRawText("");
    try {
      let imageSource = file;

      if (file.type === "application/pdf") {
        setStatusMsg("Cargando lector de PDF…");
        await loadScriptOnce("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js");
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
        setStatusMsg("Convirtiendo la primera página del PDF a imagen…");
        const buf = await file.arrayBuffer();
        const pdf = await window.pdfjsLib.getDocument({ data: buf }).promise;
        const page = await pdf.getPage(1);
        const viewport = page.getViewport({ scale: 2 });
        const canvas = document.createElement("canvas");
        canvas.width = viewport.width;
        canvas.height = viewport.height;
        await page.render({ canvasContext: canvas.getContext("2d"), viewport }).promise;
        imageSource = canvas;
      }

      setStatusMsg("Cargando OCR…");
      await loadScriptOnce("https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js");

      setStatusMsg("Leyendo el documento (puede tardar 10-30 segundos)…");
      const { data } = await window.Tesseract.recognize(imageSource, "spa+eng", {
        logger: (m) => {
          if (m.status === "recognizing text") setStatusMsg(`Leyendo el documento… ${Math.round((m.progress || 0) * 100)}%`);
        },
      });

      setRawText(data.text);
      const guess = guessGpaFromText(data.text);
      setStatus("done");
      setStatusMsg(guess ? "Listo — revisá que el número extraído sea el correcto." : "No pude identificar un promedio automáticamente — revisá el texto leído y cargalo a mano.");
      onExtracted(guess);
    } catch (err) {
      setStatus("error");
      setStatusMsg("No se pudo leer el archivo. Probá con otra foto (más luz, más derecha) o cargá el promedio a mano.");
    }
  }

  return (
    <div className="rm-gpa-upload">
      <label className="rm-field-label-standalone">Subí tu boletín (PDF, JPG o PNG) para autocompletar — opcional</label>
      <input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={handleFile} disabled={status === "loading"} />
      {status === "loading" && <div className="rm-gpa-ocr-status">⏳ {statusMsg}</div>}
      {status === "done" && <div className="rm-gpa-ocr-status">✓ {statusMsg}</div>}
      {status === "error" && <div className="rm-gpa-ocr-status rm-gpa-ocr-error">⚠ {statusMsg}</div>}
      {rawText && (
        <details style={{ marginTop: 8 }}>
          <summary style={{ cursor: "pointer", fontSize: 12, color: "var(--ink-soft)" }}>Ver texto leído del documento (para verificar)</summary>
          <pre className="rm-gpa-ocr-raw">{rawText}</pre>
        </details>
      )}
      <p className="rm-hint" style={{ marginTop: 6 }}>Esto corre un OCR gratuito directo en tu navegador (no se sube el archivo a ningún servidor). Es más flojo con letra manuscrita, fotos torcidas o boletines con tablas complejas — siempre revisá el número antes de usarlo.</p>
    </div>
  );
}

// ---- Buscar universidades por carrera (combina ajuste académico real con el ranking deportivo) ----
// Candidatas: toda escuela con dato académico, sea del Common Data Set (31, más rico) o de College Scorecard
// (1.367, solo licenciatura). No repetimos la lógica de checkAcademicFit: la reusamos tal cual para que el
// resultado de esta página sea siempre igual al que ve la atleta en su ranking.
const CAREER_CANDIDATES = Array.from(new Set([...Object.keys(CDS_DATA), ...Object.keys(MAJOR_DATA_BY_SCHOOL), ...EADA_DATA.filter((e) => e.car).map((e) => EADA_DISPLAY_NAME.get(e.u) || e.n)]));
const COMMON_MAJORS = Object.keys(MAJOR_ES_EN).map((k) => k.replace(/\b\w/g, (c) => c.toUpperCase()));

function searchUniversitiesByCareer(majorWanted, profile) {
  const wanted = String(majorWanted || "").trim();
  if (!wanted) return [];
  const sportResults = profile ? (() => { try { return runMatch(profile); } catch (e) { return []; } })() : [];
  const sportByUni = new Map(sportResults.map((r) => [r.university, r]));
  const catalogByName = new Map(PROGRAMS_ALL_SPORTS.filter((p) => !profile || (p.sport === profile.sport && (!p.Gender || p.Gender === profile.gender))).map((p) => [p.School, p]));
  const rows = [];
  for (const school of CAREER_CANDIDATES) {
    const fit = checkAcademicFit(school, wanted);
    if (fit.status !== "confirmado_si") continue;
    const name = fit.cds ? wanted : fit.scorecard ? fit.scorecard.name : fit.ipeds.name;
    const earn4 = fit.scorecard ? fit.scorecard.earn4 : null;
    const earn5 = fit.scorecard ? fit.scorecard.earn5 : null;
    const cat = catalogByName.get(school);
    const sport = sportByUni.get(school) || null;
    const e = eadaFor(school);
    const team = profile && e ? eadaTeamSize(e, profile.sport, profile.gender) : null;
    const gi = profile && profile.gender === "F" ? 1 : 0;
    rows.push({
      school, source: fit.cds ? "cds" : fit.scorecard ? "scorecard" : "ipeds", careerName: name, earn4, earn5,
      levelText: fit.ipeds ? ipedsLevelText(fit.ipeds) : null,
      division: (cat && cat.Division) || (e && eadaDivision(e.cls)) || (fit.cds && "—") || null,
      place: cat ? `${cat.City}, ${cat.State}` : e ? `${e.city || ""}${e.city ? ", " : ""}${e.st}` : null,
      sportScore: sport ? sport.score : null, hasRoster: sport ? !!(ROSTERS_LOADED[school] || ROSTERS_LOADED[`${school}::${profile.sport}`]) : false,
      hasTeam: !!team, givesAid: !!(profile && e && team && e.aid[gi] > 0),
    });
  }
  // orden: primero las que además tienen fit deportivo confirmado (perfil cargado), después las que tienen el deporte con becas
  // en la rama del atleta (EADA), después por ganancia a 5 años y a 4
  rows.sort((a, b) => (b.sportScore || -1) - (a.sportScore || -1) || (b.givesAid ? 1 : 0) - (a.givesAid ? 1 : 0) || (b.hasTeam ? 1 : 0) - (a.hasTeam ? 1 : 0) || (b.earn5 || 0) - (a.earn5 || 0) || (b.earn4 || 0) - (a.earn4 || 0));
  return rows;
}

function CareerFinderPage({ profile, onOpenSchool }) {
  const [query, setQuery] = useState(profile ? profile.major || "" : "");
  const [committed, setCommitted] = useState(query);
  const rows = useMemo(() => searchUniversitiesByCareer(committed, profile), [committed, profile]);
  const fmt = (n) => (n ? `USD ${n.toLocaleString("en-US")}` : "sin dato");

  return (
    <div className="rm-wrap" style={{ paddingTop: 40, paddingBottom: 60 }}>
      <h2 className="rm-condensed">Buscar universidades por carrera</h2>
      <p className="rm-hint">
        Escribí la carrera que querés estudiar y te mostramos qué universidades la ofrecen de verdad (confirmado con el Common Data Set
        de cada escuela, College Scorecard o IPEDS, del gobierno de EE.UU.), con la ganancia mediana de sus egresadas a los 4 y 5 años cuando está disponible.
        Incluye títulos de 2 años de junior colleges.
        {profile ? " Como ya tenés un perfil cargado, las que además tienen un buen fit en tu deporte aparecen primero, con su puntaje." : " Armá tu perfil para que también se combine con tu fit deportivo."}
      </p>
      <div className="rm-mail-field" style={{ maxWidth: 480, marginTop: 16 }}>
        <span>Carrera</span>
        <div className="rm-mail-inline">
          <input list="rm-career-list" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Ej: Ingeniería Química" onKeyDown={(e) => e.key === "Enter" && setCommitted(query)} />
          <datalist id="rm-career-list">{COMMON_MAJORS.map((m) => <option key={m} value={m} />)}</datalist>
          <button type="button" className="rm-btn-inline" onClick={() => setCommitted(query)}>Buscar →</button>
        </div>
      </div>

      {committed && (
        rows.length === 0 && /^pre-(law|med)$/.test(normalizeMajor(committed)) ? (
          <p className="rm-alert" style={{ marginTop: 20 }}>
            En EE.UU. {normalizeMajor(committed) === "pre-law" ? "Derecho (Law School)" : "Medicina (Medical School)"} no es una carrera de grado: se cursa después de una licenciatura de 4 años.
            Lo habitual es hacer primero una licenciatura {normalizeMajor(committed) === "pre-law" ? "como Political Science, Philosophy, History o Criminal Justice, con orientación \"pre-law\"" : "como Biology, Chemistry o Biochemistry, con el programa \"pre-med\""}. Buscá esa carrera acá.
          </p>
        ) : rows.length === 0 ? (
          <p className="rm-alert" style={{ marginTop: 20 }}>
            No encontramos ninguna universidad de nuestras {CAREER_CANDIDATES.length.toLocaleString("es")} con datos académicos que confirme "{committed}" con graduadas recientes.
            Puede existir igual (esta fuente no cubre todas las carreras de todas las escuelas): probá con el nombre en inglés o una carrera más cercana.
          </p>
        ) : (
          <>
            <p className="rm-today-note" style={{ marginTop: 16 }}>{rows.length} universidades confirmadas para "{committed}"{profile ? `, ordenadas primero por fit en ${profile.sport}` : ""}.</p>
            <div className="rm-catalog-list" style={{ marginTop: 12 }}>
              {rows.slice(0, 60).map((r) => (
                <div className="rm-catalog-row" key={r.school} onClick={() => onOpenSchool(r.school)}>
                  <div className="rm-catalog-row-main">
                    <b>{r.school}</b>
                    {r.sportScore != null && <span className="rm-fit-chip" style={{ background: "#eaf6ee", color: "#1f7a3f" }}>{r.sportScore} pts en {profile.sport}{r.hasRoster ? " · roster real" : ""}</span>}
                    {r.sportScore == null && r.givesAid && <span className="rm-fit-chip" style={{ background: "#eaf6ee", color: "#1f7a3f" }}>{profile.sport} {profile.gender === "F" ? "femenino" : "masculino"} con becas</span>}
                    {r.sportScore == null && r.hasTeam && !r.givesAid && <span className="rm-fit-chip" style={{ background: "#f1f1f1", color: "#555" }}>{profile.sport} {profile.gender === "F" ? "femenino" : "masculino"} sin becas deportivas</span>}
                    <span className="rm-fit-chip" style={{ background: r.source === "cds" ? "#eaf1fa" : r.source === "ipeds" ? "#f3eefb" : "#fff4d6", color: r.source === "cds" ? "#2f6fb3" : r.source === "ipeds" ? "#6a3fb3" : "#8a5a00" }}>{r.source === "cds" ? "Common Data Set" : r.source === "ipeds" ? "IPEDS" : "College Scorecard"}</span>
                  </div>
                  <div className="rm-catalog-row-meta">{r.division || "División sin dato"} · {r.place || "ubicación sin dato"} · carrera confirmada: {r.careerName}{r.levelText ? ` (${r.levelText})` : ""}</div>
                  {r.source !== "ipeds" && <div className="rm-catalog-row-meta">Ganancia mediana de egresadas — 4 años: {fmt(r.earn4)} · 5 años: {fmt(r.earn5)}</div>}
                </div>
              ))}
            </div>
            {rows.length > 60 && <p className="rm-today-note">Mostrando las primeras 60 de {rows.length}.</p>}
          </>
        )
      )}
      <p className="rm-exam-note" style={{ marginTop: 24 }}>
        Cobertura: {Object.keys(CDS_DATA).length} universidades con Common Data Set (solo confirma ingenierías acreditadas ABET) y {Object.keys(MAJOR_DATA_BY_SCHOOL).length} con College Scorecard
        (licenciatura, todas las carreras con al menos una graduada reciente reportada — la ausencia de una carrera acá no confirma que no exista). Datos de EE.UU., cohortes más recientes, bajados el 25/9/2026.
        {" "}Además, {EADA_DATA.filter((e) => e.car).length.toLocaleString("es")} universidades con deporte universitario tienen sus títulos de 2 y 4 años otorgados en 2024-25 según IPEDS, incluidos los junior colleges,
        y los equipos y becas deportivas de cada una según EADA 2024.
      </p>
    </div>
  );
}

function GpaCalculatorPage({ onUseInProfile }) {
  const [scale, setScale] = useState("ar10");
  const [raw, setRaw] = useState(8.0);
  const s = GPA_SCALES[scale];
  const result = Math.round(s.convert(parseFloat(raw) || 0) * 100) / 100;

  const context = Object.entries(CDS_DATA).map(([uni, cds]) => {
    let nivel;
    if (!cds.sat_range) nivel = "sin dato de percentil académico cargado";
    else nivel = result >= 3.7 ? "en el rango competitivo" : result >= 3.3 ? "por debajo del percentil típico, pero no descartable con buen perfil deportivo" : "bastante por debajo del percentil académico típico de admitidos";
    return { uni, admit_rate: cds.admit_rate, nivel };
  });

  return (
    <div className="rm-wrap" style={{ paddingTop: 40, paddingBottom: 60 }}>
      <h2 className="rm-condensed">Conversor de GPA</h2>
      <p className="rm-hint">Convertí tu promedio a la escala 4.0 que usan las universidades de EE.UU. Es una <b>estimación orientativa</b> — la conversión oficial la hace la oficina de admisiones de cada universidad o un evaluador de credenciales (WES, ECE, SpanTran), y puede variar de la que ves acá.</p>

      <GpaFileReader onExtracted={(guess) => { if (guess) setRaw(guess); }} />

      <div className="rm-grid">
        <div className="rm-field"><label>Tu sistema / escala</label>
          <select value={scale} onChange={(e) => setScale(e.target.value)}>
            {Object.entries(GPA_SCALES).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
          </select>
        </div>
        <div className="rm-field"><label>Tu promedio, en tu escala (max. {s.max})</label>
          <input type="number" step="0.01" value={raw} onChange={(e) => setRaw(e.target.value)} />
        </div>
      </div>

      <div className="rm-gpa-result">
        <div className="rm-gpa-result-big">{result.toFixed(2)} <span>/ 4.0</span></div>
        <div className="rm-gpa-formula">Cómo se calcula: {s.formula}</div>
      </div>

      {context.length > 0 && (
        <div style={{ marginTop: 30 }}>
          <h3 className="rm-condensed" style={{ fontSize: 16 }}>¿Qué significa esto en universidades reales que ya verificamos?</h3>
          <ul className="rm-reasons">
            {context.map((c) => (
              <li key={c.uni}><b>{c.uni}</b> (admisión {c.admit_rate || "no verificada"}): tu GPA convertido está {c.nivel}.</li>
            ))}
          </ul>
          <p style={{ fontSize: 12.5, color: "var(--ink-soft)", fontStyle: "italic" }}>Solo estas {context.length} universidades tienen percentiles académicos verificados hoy — para el resto del catálogo no podemos dar este contexto todavía.</p>
        </div>
      )}

      {onUseInProfile && <button className="rm-btn" style={{ marginTop: 20 }} onClick={() => onUseInProfile(scale, raw)}>Usar este GPA en mi perfil →</button>}
    </div>
  );
}

function ProfileForm({ onSubmit, initial }) {
  const [p, setP] = useState(initial ? { gradMonth: 12, ...initial } : emptyProfile);
  const set = (k) => (e) => setP({ ...p, [k]: e.target.value });
  const setNum = (k) => (e) => setP({ ...p, [k]: parseFloat(e.target.value) || 0 });

  return (
    <div className="rm-wrap">
      <div className="rm-section" style={{ borderTop: "none", paddingTop: 44 }}>
        <h2 className="rm-condensed">Tu perfil de aspirante</h2>
        <p className="rm-hint">Con esto cruzamos necesidades reales de coaches, reglas de beca por división y — donde ya tenemos roster cargado — tu nivel real contra el plantel.</p>

        <div className="rm-grid">
          <div className="rm-field"><label>Nombre</label><input value={p.name} onChange={set("name")} placeholder="Para personalizar tus emails" /></div>
          <div className="rm-field"><label>Tu email (para enviar desde ahí)</label><input type="email" value={p.email} onChange={set("email")} placeholder="tu@email.com" /></div>
          <div className="rm-field"><label>Tu teléfono (opcional, va en la firma del email)</label><input type="tel" value={p.phone} onChange={set("phone")} placeholder="+54 9 11 xxxx-xxxx" /></div>
          <div className="rm-field rm-full"><label>Link a tu video (YouTube / Hudl / Vimeo)</label><input value={p.videoLink} onChange={set("videoLink")} placeholder="https://..." /></div>
          <div className="rm-field"><label>País de origen</label><input value={p.country} onChange={set("country")} list="rm-paises" autoComplete="country-name" />
            <datalist id="rm-paises">{["Argentina", "Bolivia", "Brasil", "Chile", "Colombia", "Costa Rica", "Ecuador", "España", "Guatemala", "México", "Panamá", "Paraguay", "Perú", "República Dominicana", "Uruguay", "Venezuela"].map((c) => <option key={c} value={c} />)}</datalist></div>

          <div className="rm-field"><label>Deporte</label>
            <select value={p.sport} onChange={(e) => { const v = e.target.value; setP((q) => ({ ...q, sport: v, position: POSITION_SELECT[v] && !POSITION_SELECT[v].includes(q.position) ? "" : q.position })); }}>{SPORTS.map((s) => <option key={s} value={s}>{s}{sportHasData(s) ? "" : " (próximamente)"}</option>)}</select>
            {(() => { const cv = sportCoverage(p.sport, p.gender); const n = (x) => x.toLocaleString("es-AR");
              if (!cv.coaches && !cv.rosters) return <span style={{ fontSize: 12, color: "var(--flag)", marginTop: 2 }}>⚠ Próximamente: para este deporte y rama todavía no cargamos coaches ni planteles. Por ahora vas a ver solo las búsquedas que publican los coaches.</span>;
              if (!cv.rosters) return <span style={{ fontSize: 12, color: "var(--field-dark)", marginTop: 2 }}>✓ {n(cv.coaches)} programas con email de coaches. Todavía no hay planteles cargados: no podemos comparar tu nivel contra el equipo ni proyectar vacantes.</span>;
              return <span style={{ fontSize: 12, color: "var(--field-dark)", marginTop: 2 }}>✓ {n(cv.coaches)} programas con email de coaches y {n(cv.rosters)} planteles reales cargados.</span>; })()}
          </div>
          <div className="rm-field"><label>Género de la división</label>
            <select value={p.gender} onChange={set("gender")}><option value="F">Femenino</option><option value="M">Masculino</option></select>
          </div>

          <div className="rm-field"><label>Posición / evento / especialidad</label>
            {POSITION_SELECT[p.sport] ? (
              <select value={p.position || ""} onChange={set("position")}>
                <option value="">Elegí tu posición</option>
                {POSITION_SELECT[p.sport].map((c) => { const n = (POSITION_NAMES[p.sport] || {})[c] || [c, c]; const es = p.gender === "M" ? n[1] : n[0]; return <option key={c} value={c}>{es.charAt(0).toUpperCase() + es.slice(1)} ({c})</option>; })}
                {p.position && !POSITION_SELECT[p.sport].includes(p.position) && <option value={p.position}>{p.position} (cargada antes)</option>}
              </select>
            ) : (
              <input value={p.position} onChange={set("position")} placeholder={POSITION_PLACEHOLDER[p.sport] || "ej: Mediocampo, Velocista 400m, Viga..."} />
            )}
            {POSITION_SELECT[p.sport] && <span style={{ fontSize: 12, color: "var(--ink-soft)", marginTop: 2 }}>Solo ves posiciones de {p.sport === "Soccer" ? "fútbol" : p.sport === "Basketball" ? "básquet" : p.sport === "Volleyball" ? "vóley" : p.sport === "Field Hockey" ? "hockey" : p.sport === "Rugby" ? "rugby" : p.sport}. Los coaches publican sus búsquedas con la sigla en inglés (por ejemplo, {(() => { const c = POSITION_SELECT[p.sport][POSITION_SELECT[p.sport].length - 1]; const e = (POSITION_NAMES[p.sport] || {})[c] || [c, c]; return `${c} = ${e[p.gender === "M" ? 1 : 0]}`; })()}); en Smartrecruit siempre te mostramos la traducción al lado.</span>}
          </div>
          <div className="rm-field"><label>Año de graduación de secundaria</label><input type="number" value={p.gradYear} onChange={setNum("gradYear")} /></div>
          <div className="rm-field"><label>Mes de graduación de secundaria</label>
            <select value={p.gradMonth || 12} onChange={(e) => setP({ ...p, gradMonth: parseInt(e.target.value, 10) })}>
              {MONTHS_ES.map((m, i) => <option key={m} value={i + 1}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>)}
            </select>
          </div>
          <div className="rm-field rm-full"><label>Tu primera temporada en EE.UU. (calculada)</label>
            <div className="rm-entry-note"><b>{getEntryYear(p)}</b> · Terminás en {MONTHS_ES[(p.gradMonth || 12) - 1]} de {p.gradYear}, así que empezás a jugar la temporada {getEntryYear(p)}.</div>
          </div>

          <div className="rm-field"><label>{STAT_LABELS[p.sport] || isGoalkeeper(p) ? profileStatLabels(p, "es").goals : "Estadística clave #1 (por temporada)"}</label><input type="number" step="0.1" value={p.goals} onChange={setNum("goals")} /></div>
          <div className="rm-field"><label>{STAT_LABELS[p.sport] || isGoalkeeper(p) ? profileStatLabels(p, "es").assists : "Estadística clave #2 (por temporada)"}</label><input type="number" step="0.1" value={p.assists} onChange={setNum("assists")} /></div>
          {isGoalkeeper(p) && <div className="rm-field"><label>{GK_STAT_LABELS.es.gaa}</label><input type="number" step="0.01" min="0" value={p.gaa ?? ""} placeholder="ej: 0.85" onChange={(e) => setP({ ...p, gaa: e.target.value === "" ? "" : parseFloat(e.target.value) })} /></div>}

          <div className="rm-field"><label>Escala de tu promedio académico</label>
            <select value={p.gpaScale} onChange={set("gpaScale")}>{Object.entries(GPA_SCALES).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}</select>
          </div>
          <div className="rm-field"><label>Tu promedio, en tu escala</label><input type="number" step="0.1" value={p.gpaRaw} onChange={setNum("gpaRaw")} /></div>

          <div className="rm-field rm-full"><label>Carrera que querés estudiar</label><input value={p.major} onChange={set("major")} /></div>

          <div className="rm-field rm-full"><label>¿Qué tipo de ayuda buscás?</label>
            <select value={p.goal} onChange={set("goal")}>
              <option value="completa">Que cubra todo el costo (beca deportiva, académica y ayuda financiera combinadas)</option>
              <option value="parcial">Una parte del costo</option>
              <option value="cualquiera">Cualquier ayuda (deportiva, académica o financiera)</option>
            </select>
          </div>
          <div className="rm-field"><label>¿Cuánto puede pagar tu familia por año? (USD)</label><input type="number" min="0" step="500" value={p.familyBudget ?? ""} placeholder="ej: 5000" onChange={(e) => setP({ ...p, familyBudget: e.target.value === "" ? "" : Math.max(0, parseFloat(e.target.value) || 0) })} /></div>
          <div className="rm-field"><label>Ingresos anuales de tu familia (aproximado)</label>
            <select value={p.familyIncome || ""} onChange={set("familyIncome")}>{INCOME_RANGES.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}</select>
          </div>
          <p className="rm-hint rm-full" style={{ margin: 0 }}>Con esto calculamos si cada universidad podría cubrir todo el costo combinando beca deportiva, académica y ayuda por necesidad. Incluí lo que puedan aportar entre toda la familia. Solo se usa para el cálculo.</p>
        </div>

        <ConsentFields value={p.consent} onChange={(c) => setP({ ...p, consent: c })} />
        <div className="rm-actions">
          <button className="rm-btn" disabled={!consentIsValid(p.consent)} style={consentIsValid(p.consent) ? undefined : { opacity: 0.5, cursor: "not-allowed" }}
            onClick={() => { if (consentIsValid(p.consent)) onSubmit({ ...p, consent: { ...p.consent, version: LEGAL_VERSION, acceptedAt: (p.consent && p.consent.version === LEGAL_VERSION && p.consent.acceptedAt) || new Date().toISOString() } }); }}>Ver mis 10 universidades →</button>
          {!consentIsValid(p.consent) && <p className="rm-today-note" style={{ marginTop: 8 }}>Para seguir, contestá si sos mayor de edad y aceptá los Términos y la Política de Privacidad{p.consent && p.consent.minor ? ", con los datos y la conformidad de tu madre, padre o tutor" : ""}.</p>}
        </div>
      </div>
    </div>
  );
}

function CoachCard({ r }) {
  if (!r.coachContact) {
    // Roster cargado pero todavía sin contacto del coach: no se muestra un botón vacío.
    return <div className="rm-missing">Todavía no tenemos el contacto del coach de esta universidad — buscalo en la ficha de la universidad o en su sitio deportivo.</div>;
  }
  if (!r.coachName) {
    // Resultado de FieldLevel: no tenemos nombre/email/teléfono real del coach, solo el link de perfil.
    return <a className="rm-contact" href={r.coachContact} target="_blank" rel="noreferrer">{r.coachLabel} →</a>;
  }
  const isEmail = r.coachContact.startsWith("mailto:");
  const email = isEmail ? r.coachContact.replace("mailto:", "") : null;
  return (
    <div className="rm-coach-card">
      <div className="rm-coach-card-name">{r.coachName}</div>
      <div className="rm-coach-card-title">{r.coachTitle}</div>
      <div className="rm-coach-card-row"><span>Email</span><b>{email || "No público"}</b></div>
      <div className="rm-coach-card-row"><span>Teléfono</span><b>{r.coachPhone || "No público"}</b></div>
      <a className="rm-contact" href={r.coachContact} target={isEmail ? undefined : "_blank"} rel={isEmail ? undefined : "noreferrer"}>
        {isEmail ? "Escribir por email →" : "Ver perfil del coach →"}
      </a>
    </div>
  );
}

function ResultCard({ r, profile, onOpenSchool, isFav, toggleFav }) {
  const hardFail = r.academicFit && r.academicFit.status === "confirmado_no";
  const cls = hardFail ? "lo" : r.score >= 60 ? "hi" : r.score >= 35 ? "mid" : "lo";
  return (
    <div className={`rm-card ${cls}`}>
      <div className="rm-card-band" />
      <div className="rm-card-body">
      {hardFail && (
        <div className="rm-alert">⚠ FILTRO DURO: esta universidad no ofrece la carrera que pediste, según su Common Data Set real. Sigue apareciendo porque el fit deportivo puede ser igual de interés — pero si la carrera es innegociable, no es tu universidad.</div>
      )}
      <div className="rm-card-top">
        <div>
          <h3 className="rm-condensed">{onOpenSchool ? <button className="rm-link-btn" onClick={() => onOpenSchool(r.university)}>{r.university}</button> : r.university}</h3>
          <div className="rm-card-meta">{r.division} · {r.place || "ubicación no especificada"} · {r.source}</div>
          {toggleFav && (
            <button className={`rm-fav-btn ${isFav && isFav(r.university) ? "rm-fav-on" : ""}`} style={{ marginTop: 6 }} onClick={() => toggleFav(r.university)}>
              {isFav && isFav(r.university) ? "★ En mi lista" : "☆ Guardar en mi lista"}
            </button>
          )}
        </div>
        <div style={{ textAlign: "right" }}>
          <div className="rm-score">{r.score}<small>PTS</small></div>
          {!hardFail && (() => {
            const fit = classifyFit(r.score);
            return <span className="rm-fit-chip" style={{ background: fit.color + "1a", color: fit.color, marginTop: 4, display: "inline-block" }}>{fit.label}</span>;
          })()}
        </div>
      </div>

      {r.vacancy && (
        <div className="rm-vacancy">
          <span className={`rm-vacancy-chip ${r.vacancy.confidence}`}>Vacante proyectada: {r.vacancy.confidence}</span>
          <span>
            {r.vacancy.known > 0
              ? `Temporada ${r.vacancy.entrySeason} · ${r.vacancy.gone} de ${r.vacancy.known} en tu posición ya no estarían · ${r.vacancy.stays} seguirían`
              : `Temporada ${r.vacancy.entrySeason} · sin año de clase en el roster para proyectar`}
          </span>
        </div>
      )}
      <CoachCard r={r} />
      <ComposeLinks profile={profile} r={r} />

      <details className="rm-card-more">
        <summary>Ver por qué y más datos</summary>
        <FitScoreBlock r={r} profile={profile} />
        <CoverageBlock r={r} profile={profile} />
        <ul className="rm-reasons">{r.reasons.map((x, i) => <li key={i}>{x}</li>)}</ul>
        <div className="rm-sch"><b>Beca típica en esta división:</b> {r.scholarship.tipo}. Banda estimada: {r.scholarship.banda}.</div>
        {r.nationalityMatch === true && <div className="rm-nat">Hay jugadoras de tu misma nacionalidad en este plantel — buen punto de partida para el primer email.</div>}
        {r.nationalityMatch === false && <div className="rm-missing">No hay jugadoras de tu nacionalidad en el roster cargado (no descarta nada, solo no suma este punto extra).</div>}
        <div className="rm-missing">Falta para afinar: {r.missing.join(" · ")}.</div>
        <SchoolProfileBlock university={r.university} />
      </details>
      </div>
    </div>
  );
}

// Bloque compacto con datos de admisión/costo/ubicación reales de NCSA,
// cuando existen para esta universidad. No inventa nada: si un campo
// no vino en el scrape, simplemente no se muestra esa línea.
function SchoolProfileBlock({ university }) {
  const p = SCHOOL_PROFILES_NCSA[university];
  if (!p) return null;
  const money = (v) => (v ? `USD ${Number(String(v).replace(/,/g, "")).toLocaleString("en")}` : null);
  return (
    <div className="rm-profile">
      <details>
        <summary>Ficha de la universidad (admisión, costo, ubicación)</summary>
        <ul className="rm-profile-list">
          {p.college_type && <li><b>Tipo:</b> {p.college_type}{p.year_founded ? ` — fundada en ${p.year_founded}` : ""}</li>}
          {p.enrollment && <li><b>Estudiantes de grado:</b> {Number(p.enrollment).toLocaleString("en")}</li>}
          {(p.tuition_in_state || p.tuition_out_state) && (
            <li><b>Matrícula anual (list price, sin ayuda):</b> {money(p.tuition_out_state || p.tuition_in_state)}{p.tuition_in_state && p.tuition_out_state && p.tuition_in_state !== p.tuition_out_state ? ` (in-state: ${money(p.tuition_in_state)})` : ""}</li>
          )}
          {p.selectivity && <li><b>Selectividad:</b> {p.selectivity}</li>}
          {p.admissions_email && <li><b>Admisiones:</b> {p.admissions_email}{p.admissions_phone ? ` · ${p.admissions_phone}` : ""}</li>}
          {p.common_app && <li><b>Common App:</b> {p.common_app === "Yes" ? "sí" : "no"}{p.early_decision === "Yes" ? ` · Early Decision: ${p.early_decision_date || "sí"}` : ""}{p.early_action === "Yes" ? ` · Early Action: ${p.early_action_date || "sí"}` : ""}</li>}
          {p.closest_major_city && <li><b>Ciudad grande más cercana:</b> {p.closest_major_city}{p.distance_major_city ? ` (${p.distance_major_city})` : ""}</li>}
          {(p.pct_male || p.pct_female) && <li><b>Composición de género del campus:</b> {p.pct_female} mujeres / {p.pct_male} varones</li>}
          {p.student_faculty_ratio && <li><b>Ratio estudiante/docente:</b> {p.student_faculty_ratio}</li>}
        </ul>
      </details>
    </div>
  );
}

/* ---------------------------------------------------------------
   RECRUIT SCORE — resumen del perfil del aspirante, estilo dashboard
   (inspirado en el layout de NextCommit, con nuestros propios
   criterios: afinidad nacional, carrera, presupuesto, género).
--------------------------------------------------------------- */
// Benchmark de GPA (escala 4.0) razonable para un atleta reclutado por división —
// no es el promedio general de admitidos, es el piso realista para reclutamiento deportivo.
const ACADEMIC_GPA_BENCHMARK = { "NCAA D1": 3.4, "NCAA D2": 3.0, "NCAA D3": 3.4, "NAIA": 2.7, "NJCAA D1": 2.3, "NJCAA": 2.3 };
const UPSIDE_BY_YEARS_REMAINING = [15, 35, 60, 85, 100];

// Clasifica un match puntual como Reach/Target/Safety según su score de compatibilidad —
// misma lógica que "Target School Alignment" de NextCommit, aplicada a cada universidad.
function classifyFit(score) {
  if (score >= 65) return { label: "Safety", color: "#1f7a3f" };
  if (score >= 35) return { label: "Target", color: "#2f6fb3" };
  return { label: "Reach", color: "#b3401a" };
}

function computeRecruitScore(profile, results) {
  const qualifying = results.filter((r) => r.academicFit?.status !== "confirmado_no").slice(0, 6);
  const pool = qualifying.length ? qualifying : results.slice(0, 6);

  // Talent score: promedio del score de los mejores matches, reescalado.
  const top = pool.slice(0, 3);
  const matchTalent = top.length ? Math.round(top.reduce((s, r) => s + r.score, 0) / top.length) : 0;

  const talent = matchTalent;

  // Años restantes hasta graduarse del secundario — proxy de cuánto margen
  // de desarrollo físico/deportivo le queda al atleta antes de anotarse.
  const currentYear = new Date().getFullYear();
  const yearsRemaining = Math.max(0, Math.min(4, (profile.gradYear || currentYear) - currentYear));

  // División proyectada: la más frecuente entre los mejores matches con score decente.
  const divCounts = {};
  pool.forEach((r) => { if (r.score >= 30) divCounts[r.division] = (divCounts[r.division] || 0) + 1; });
  const divisions = Object.entries(divCounts).sort((a, b) => b[1] - a[1]).map(([d]) => d);
  const projectedDivision = divisions.length ? divisions.slice(0, 2).map((d) => d.replace("NCAA ", "")).join("/") : "Sin datos suficientes";

  // Rango de ayuda en USD: combina % de la beca típica con el costo real (CDS) de las universidades del top.
  let low = null, high = null;
  pool.forEach((r) => {
    const cds = r.academicFit?.cds;
    const sch = r.scholarship;
    if (cds && sch && typeof sch.pctLow === "number") {
      const l = Math.round((cds.cost_of_attendance_usd * sch.pctLow) / 100);
      const h = Math.round((cds.cost_of_attendance_usd * sch.pctHigh) / 100);
      if (low === null || l < low) low = l;
      if (high === null || h > high) high = h;
    }
  });

  // Exposure: proxy real basado en cuántos emails generó/envió desde este navegador (localStorage).
  let outreachCount = 0;
  try { outreachCount = parseInt(localStorage.getItem("rr_outreach_count") || "0", 10); } catch (e) {}
  const exposure = Math.min(100, outreachCount * 8);

  const natMatches = pool.filter((r) => r.nationalityMatch === true).length;

  // ---- Los 4 pilares (inspirados en el desglose de NextCommit, con datos propios) ----
  // 1) Athletic Profile — proxy basado en el match con necesidades publicadas y planteles reales.
  const athleticScore = matchTalent;

  // 2) Academic Fit & Eligibility — GPA convertido a 4.0 contra el piso realista de la división dominante.
  const gpaScaleObj = GPA_SCALES[profile.gpaScale] || GPA_SCALES.ar10;
  const gpa4 = gpaScaleObj ? gpaScaleObj.convert(parseFloat(profile.gpaRaw) || 0) : parseFloat(profile.gpaRaw) || 0;
  const academicBenchmark = ACADEMIC_GPA_BENCHMARK[divisions[0]] ?? 3.0;
  const academicScore = Math.max(0, Math.min(100, Math.round(50 + (gpa4 - academicBenchmark) * 80)));

  // 3) Recruiting Momentum & Outreach Activity — exposure real + tener video cargado.
  const momentumScore = Math.min(100, Math.round(exposure * 0.75 + (profile.videoLink ? 25 : 0)));

  // 4) Current Readiness vs. Long-Term Upside — separa "hoy" de "cuánto margen de desarrollo queda".
  const readinessScore = talent;
  const upsideScore = UPSIDE_BY_YEARS_REMAINING[yearsRemaining] ?? 50;

  // Alineación de la lista: cuántos de los matches del pool son Reach/Target/Safety.
  const fitCounts = { Reach: 0, Target: 0, Safety: 0 };
  pool.forEach((r) => { fitCounts[classifyFit(r.score).label]++; });

  // Gaps concretos — solo se listan los que de verdad aplican, nada relleno.
  const gaps = [];
  if (academicScore < 40) gaps.push(`Tu GPA (${gpa4.toFixed(2)}/4.0) está por debajo del piso realista de ${divisions[0] || "la división que estás apuntando"} (${academicBenchmark.toFixed(1)}) — es lo primero que filtra a un coach antes de mirar tu video.`);
  if (!profile.videoLink) gaps.push("No tenés un link de video de highlights cargado en tu perfil — es el primer filtro que aplica casi cualquier coach.");
  if (outreachCount === 0) gaps.push("Todavía no le escribiste a ningún coach — el score de Recruiting Momentum queda en el piso hasta que generes el primer email real.");
  if (fitCounts.Reach > fitCounts.Target + fitCounts.Safety) gaps.push(`De tus universidades con match, ${fitCounts.Reach} son Reach y solo ${fitCounts.Target + fitCounts.Safety} son Target/Safety — conviene sumar algunas más realistas a tu lista antes de escribir.`);

  return {
    talent, matchTalent, yearsRemaining, projectedDivision, low, high, exposure, outreachCount, natMatches, pool,
    athleticScore, academicScore, momentumScore, readinessScore, upsideScore, gpa4, academicBenchmark, fitCounts, gaps,
  };
}


function RecruitScoreCard({ profile, results }) {
  const rs = computeRecruitScore(profile, results);
  const talentColor = rs.talent >= 60 ? "var(--field)" : rs.talent >= 35 ? "var(--gold)" : "var(--flag)";
  const circumference = 2 * Math.PI * 54;
  const dash = (rs.talent / 100) * circumference;

  const analysis = (() => {
    const parts = [];
    parts.push(`Perfil de ${profile.sport}${profile.position ? " en " + profile.position : ""} de ${profile.country}, ingreso proyectado a la temporada ${getEntryYear(profile)}.`);
    if (rs.natMatches > 0) parts.push(`Hay ${rs.natMatches} universidad(es) en tu top con compatriotas reales en el plantel — ventaja de adaptación real, no solo estadística. (Solo miramos jugadoras: la nacionalidad del cuerpo técnico todavía no está cargada.)`);
    else parts.push(`Ninguna de tus mejores matches tiene compatriotas confirmadas todavía en el roster — no es descalificador, pero tu primer email va a tener que venderte más por mérito deportivo/académico que por afinidad.`);
    if (rs.talent >= 60) parts.push(`Tu score de talento (${rs.talent}/100) surge de necesidades reales publicadas + comparación contra planteles reales — es un perfil competitivo para las universidades de tu top.`);
    else if (rs.talent >= 30) parts.push(`Tu score de talento (${rs.talent}/100) es moderado — hay matches reales, pero probablemente en un escalón más aterrizado (D2/D3/NAIA) que D1 de élite.`);
    else parts.push(`Tu score de talento (${rs.talent}/100) es bajo con los datos actuales — puede ser por falta de necesidad publicada compatible, filtro académico duro, o pocos matches con roster real cargado para tu deporte.`);

    if (rs.yearsRemaining >= 2 && rs.talent >= 30 && rs.talent < 65) parts.push(`Te quedan ${rs.yearsRemaining} años hasta graduarte del secundario — con ese margen de desarrollo, tu techo real probablemente esté un escalón por encima de lo que muestra el score de hoy, siempre que sigas sumando partidos/marcas.`);
    else if (rs.yearsRemaining <= 1 && rs.talent < 60) parts.push(`Con ${rs.yearsRemaining === 0 ? "menos de un año" : "un año"} hasta graduarte, queda poco margen para subir el score con desarrollo físico — el foco ahora debería estar en outreach y en cerrar con las universidades donde ya matcheás bien, no en esperar a mejorar métricas.`);

    if (rs.low !== null) parts.push(`El rango de ayuda estimado (USD ${rs.low.toLocaleString("en")}–${rs.high.toLocaleString("en")}/año) sale de cruzar el % de beca típico de la división con el costo real de asistencia de esas universidades — no es una oferta, es un techo/piso realista.`);
    parts.push(rs.outreachCount > 0 ? `Ya generaste ${rs.outreachCount} email(s) personalizados desde este navegador — eso es lo que mueve tu exposure real.` : `Todavía no generaste ningún email desde acá — tu exposure está en 0 hasta que le escribas a algún coach.`);
    return parts.join(" ");
  })();

  return (
    <div className="rm-recruit-score">
      <div className="rm-recruit-top">
        <div className="rm-recruit-gauge">
          <svg viewBox="0 0 120 120" width="120" height="120">
            <circle cx="60" cy="60" r="54" fill="none" stroke="var(--line)" strokeWidth="10" />
            <circle cx="60" cy="60" r="54" fill="none" stroke={talentColor} strokeWidth="10" strokeDasharray={`${dash} ${circumference}`} strokeLinecap="round" transform="rotate(-90 60 60)" />
          </svg>
          <div className="rm-recruit-gauge-num">
            <b>{rs.talent}</b>
            <span>TALENTO</span>
          </div>
        </div>
        <div className="rm-recruit-boxes">
          <div className="rm-recruit-box">
            <span>⚡ EXPOSURE</span>
            <b>{rs.exposure} <small>/ 100</small></b>
            <div className="rm-recruit-bar"><div style={{ width: `${rs.exposure}%` }} /></div>
          </div>
          <div className="rm-recruit-box">
            <span>📍 DIVISIÓN PROYECTADA</span>
            <b>{rs.projectedDivision}</b>
          </div>
          <div className="rm-recruit-box">
            <span>⏳ AÑOS DE DESARROLLO</span>
            <b>{rs.yearsRemaining} <small>hasta graduarte</small></b>
          </div>
          <div className="rm-recruit-box rm-recruit-box-wide">
            <span>📈 AYUDA ESTIMADA (BECA + FINANCIAL AID)</span>
            <b>{rs.low !== null ? `USD ${rs.low.toLocaleString("en")} – ${rs.high.toLocaleString("en")}` : "Sin datos de costo suficientes en tu top"}{rs.low !== null && <small> / año</small>}</b>
          </div>
        </div>
      </div>
      <div className="rm-recruit-analysis">
        <h4>Análisis</h4>
        <p>{analysis}</p>
      </div>

      <div className="rm-recruit-pillars">
        <h4>Desglose por pilar</h4>
        <div className="rm-pillar-grid">
          <div className="rm-pillar">
            <span>🏃 ATHLETIC PROFILE</span>
            <b>{rs.athleticScore}<small>/100</small></b>
            <div className="rm-recruit-bar"><div style={{ width: `${rs.athleticScore}%` }} /></div>
            <p>Estimado a partir del match con necesidades publicadas y planteles reales.</p>
          </div>
          <div className="rm-pillar">
            <span>🎓 ACADEMIC FIT</span>
            <b>{rs.academicScore}<small>/100</small></b>
            <div className="rm-recruit-bar"><div style={{ width: `${rs.academicScore}%` }} /></div>
            <p>Tu {rs.gpa4.toFixed(2)}/4.0 vs. piso realista de {(rs.academicBenchmark).toFixed(1)} para reclutamiento en esa división.</p>
          </div>
          <div className="rm-pillar">
            <span>📨 RECRUITING MOMENTUM</span>
            <b>{rs.momentumScore}<small>/100</small></b>
            <div className="rm-recruit-bar"><div style={{ width: `${rs.momentumScore}%` }} /></div>
            <p>Emails generados + video cargado. {rs.outreachCount === 0 && "Todavía en cero — el primer email lo mueve más que cualquier otra cosa."}</p>
          </div>
          <div className="rm-pillar">
            <span>📈 READINESS vs. UPSIDE</span>
            <b>{rs.readinessScore}<small>/{rs.upsideScore}</small></b>
            <div className="rm-recruit-bar"><div style={{ width: `${rs.readinessScore}%` }} /></div>
            <p>Hoy: {rs.readinessScore}/100 · Margen de desarrollo ({rs.yearsRemaining} años restantes): {rs.upsideScore}/100.</p>
          </div>
        </div>
      </div>

      {rs.pool.length > 0 && (
        <div className="rm-recruit-fit-summary">
          <span className="rm-fit-chip" style={{ background: "#fdeceb", color: "#b3401a" }}>{rs.fitCounts.Reach} Reach</span>
          <span className="rm-fit-chip" style={{ background: "#eaf1fa", color: "#2f6fb3" }}>{rs.fitCounts.Target} Target</span>
          <span className="rm-fit-chip" style={{ background: "#eaf6ee", color: "#1f7a3f" }}>{rs.fitCounts.Safety} Safety</span>
          <span style={{ fontSize: 12, color: "var(--ink-soft)" }}>— así se reparte tu lista de matches. Cada resultado abajo muestra su propia etiqueta.</span>
        </div>
      )}

      {rs.gaps.length > 0 && (
        <div className="rm-recruit-gaps">
          <h4>Gaps y plan de acción</h4>
          <ul>{rs.gaps.map((g, i) => <li key={i}>{g}</li>)}</ul>
        </div>
      )}

      <RecruitScoreSimulator profile={profile} results={results} baseRs={rs} />
    </div>
  );
}

// Simulador "¿y si...?" — el atleta mueve su GPA y ve cómo cambiaría
// su Recruit Score en vivo, sin tocar su perfil real. Reusa computeRecruitScore
// con un perfil clonado y modificado.
function RecruitScoreSimulator({ profile, results, baseRs }) {
  const [open, setOpen] = useState(false);
  const gpaScaleObj = GPA_SCALES[profile.gpaScale] || GPA_SCALES.ar10;
  const [gpaRaw, setGpaRaw] = useState(profile.gpaRaw || (gpaScaleObj.max ? gpaScaleObj.max * 0.75 : 8));

  const simProfile = useMemo(() => {
    const gpa4 = gpaScaleObj.convert(parseFloat(gpaRaw) || 0);
    return { ...profile, gpaRaw, gpa4: Math.round(gpa4 * 100) / 100 };
  }, [gpaRaw]);

  const simRs = useMemo(() => computeRecruitScore(simProfile, results), [simProfile, results]);
  const delta = simRs.talent - baseRs.talent;

  return (
    <div className="rm-recruit-sim">
      <button className="rm-sim-toggle" onClick={() => setOpen(!open)}>
        {open ? "▲ Cerrar simulador" : "🎯 Simular: ¿cómo sube mi score si mejoro?"}
      </button>
      {open && (
        <div className="rm-sim-body">
          <p style={{ fontSize: 13, color: "var(--ink-soft)", margin: "0 0 16px" }}>Mové la barra para ver, en vivo, cuánto cambiaría tu Recruit Score si mejorás. No toca tu perfil real — es solo para que veas dónde te conviene poner el esfuerzo.</p>

          <div className="rm-sim-controls">
            <div className="rm-sim-control">
              <label>Tu promedio ({gpaScaleObj.label.split("(")[0].trim()}): <b>{parseFloat(gpaRaw).toFixed(1)}</b> <span className="rm-sim-conv">= {simProfile.gpa4} en escala 4.0</span></label>
              <input type="range" min={gpaScaleObj.max ? gpaScaleObj.max * 0.4 : 4} max={gpaScaleObj.max || 10} step="0.1" value={gpaRaw} onChange={(e) => setGpaRaw(e.target.value)} />
            </div>
          </div>

          <div className="rm-sim-result">
            <div className="rm-sim-score-block">
              <div className="rm-sim-score-label">Score simulado</div>
              <div className="rm-sim-score-num">{simRs.talent}<small>/100</small></div>
              {delta !== 0 && (
                <div className={`rm-sim-delta ${delta > 0 ? "up" : "down"}`}>{delta > 0 ? "▲ +" : "▼ "}{delta} vs. tu score actual ({baseRs.talent})</div>
              )}
              {delta === 0 && <div className="rm-sim-delta">= igual a tu score actual</div>}
            </div>
            <div className="rm-sim-detail">
              <div>Académico: <b>{simRs.academicScore}/100</b></div>
              <div>División proyectada: <b>{simRs.projectedDivision}</b></div>
            </div>
          </div>

          {delta > 8 && <div className="rm-alert" style={{ marginTop: 14 }}>Esa mejora te subiría el score {delta} puntos — vale la pena el esfuerzo. Cuando lo logres de verdad, actualizá tu perfil para que quede registrado.</div>}
        </div>
      )}
    </div>
  );
}

// Síntesis en una sola voz de cuál es la mejor opción real hoy — el paso de
// interpretación que haría una agencia, hecho automáticamente a partir de los
// mismos datos reales que ya arma cada tarjeta (vacante + necesidad + nivel +
// academia + plata). Se salta cualquier match con filtro académico confirmado
// en contra (hardFail), aunque tenga el score más alto.
function BestOptionCard({ profile, results, onOpenSchool }) {
  const best = results.find((r) => !(r.academicFit && r.academicFit.status === "confirmado_no"));
  if (!best) return null;
  const fit = classifyFit(best.score);

  return (
    <div className="rm-best-option">
      <div className="rm-best-option-label">Tu mejor opción real, hoy</div>
      <h3 className="rm-condensed" style={{ fontSize: 26, margin: "4px 0 2px" }}>
        {onOpenSchool ? <button className="rm-link-btn" onClick={() => onOpenSchool(best.university)}>{best.university}</button> : best.university}
      </h3>
      <div className="rm-card-meta">
        {best.division} · {best.place || "ubicación no especificada"} · Score {best.score}/100 · <span style={{ color: fit.color, fontWeight: 700 }}>{fit.label}</span>
      </div>
      <p className="rm-best-option-why">
        <b>Por qué es tu mejor opción:</b> {best.reasons.join(" ")}
      </p>
      <ComposeLinks profile={profile} r={best} />
      <button
        className="rm-btn-inline"
        style={{ marginTop: 10 }}
        onClick={() => { const el = document.getElementById("rm-full-results"); if (el) el.scrollIntoView({ behavior: "smooth" }); }}
      >
        Ver el resto de tus opciones ↓
      </button>
    </div>
  );
}

function Results({ profile, onBack, onOpenSchool }) {
  const results = useMemo(() => runMatch(profile), [profile]);
  const extra = useMemo(() => { try { return matchFromEada(profile, new Set(results.map((r) => r.university))); } catch (e) { return []; } }, [profile, results]);
  const [favs, toggleFav, isFav] = useFavorites();
  return (
    <div className="rm-wrap" style={{ paddingTop: 40, paddingBottom: 40 }}>
      <button className="rm-back" onClick={onBack}>← Editar mi perfil</button>
      <h2 className="rm-condensed" style={{ fontSize: 26, marginBottom: 6 }}>
        {results.length} universidades para {profile.name || "tu perfil"}, {profile.sport} {profile.gender === "F" ? "femenino" : "masculino"}, ingreso {getEntryYear(profile)}
      </h2>
      <p className="rm-hint" style={{ marginBottom: 20 }}>
        Ordenadas por score explicado (necesidad real + nivel vs. plantel donde hay roster + realismo de beca por división). No son promesas — son puntos de partida para escribirle al coach.
      </p>
      {results.length > 0 && <BestOptionCard profile={profile} results={results} onOpenSchool={onOpenSchool} />}
      {results.length > 0 && <RecruitScoreCard profile={profile} results={results} />}
      <button className="rm-btn-ghost" style={{ margin: "26px 0", fontSize: 13 }} onClick={() => downloadWeeklyReminderICS(profile)}>
        📅 Descargar recordatorio semanal (.ics — Google/Outlook/Apple Calendar)
      </button>
      {results.length === 0 && <p>No encontramos necesidades publicadas para esa combinación de deporte/género todavía. Probá otra posición o revisá el deporte elegido.</p>}
      <div id="rm-full-results">
        {results.map((r, i) => <ResultCard key={i} r={r} profile={profile} onOpenSchool={onOpenSchool} isFav={isFav} toggleFav={toggleFav} />)}
      </div>
      {extra.length > 0 && (
        <div id="rm-eada-results" style={{ marginTop: 40 }}>
          <h2 className="rm-condensed" style={{ fontSize: 22, marginBottom: 6 }}>
            También te conviene escribirles: {extra.length} programas sin búsqueda publicada
          </h2>
          <p className="rm-hint" style={{ marginBottom: 20 }}>
            Tienen {profile.sport} {profile.gender === "F" ? "femenino" : "masculino"}, dan becas deportivas{profile.major ? ` y ofrecen ${profile.major}` : ""} según datos oficiales de EE.UU. (EADA 2024 e IPEDS 2024-25), incluidos junior colleges.
            Todavía no publicaron una búsqueda ni tenemos su roster, por eso el puntaje es más bajo: el primer contacto lo iniciás vos.
          </p>
          {extra.map((r, i) => <ResultCard key={`e${i}`} r={r} profile={profile} onOpenSchool={onOpenSchool} isFav={isFav} toggleFav={toggleFav} />)}
        </div>
      )}
    </div>
  );
}

const BG_SPORTS_IMAGE = "data:image/jpeg;base64,";

// Onboarding guiado — el "¿y ahora qué?" para el que llega perdido. Detecta el
// progreso real (perfil, GPA, favoritos, emails generados, checklist elegibilidad)
// y va marcando pasos como hechos. Baja la fricción del que hace todo por cuenta propia.
function OnboardingPanel({ profile, setStage }) {
  const [dismissed, setDismissed] = useState(() => {
    try { return localStorage.getItem("rr_onboarding_dismissed") === "1"; } catch (e) { return false; }
  });

  const hasProfile = !!(profile && profile.name && profile.sport);
  const hasGpa = !!(profile && profile.gpa4);
  let favCount = 0, outreachCount = 0, eligDone = false;
  try {
    favCount = JSON.parse(localStorage.getItem("rr_favorites") || "[]").length;
    outreachCount = parseInt(localStorage.getItem("rr_outreach_count") || "0", 10);
    const elig = JSON.parse(localStorage.getItem("rr_eligibility_checklist") || "{}");
    eligDone = Object.values(elig).some(Boolean);
  } catch (e) {}

  const steps = [
    { id: "profile", n: 1, title: "Armá tu perfil", desc: "Deporte, posición, año y promedio. 2 minutos.", done: hasProfile, goto: "form", cta: hasProfile ? "Editar mi perfil" : "Empezar ahora →" },
    { id: "results", n: 2, title: "Mirá tus universidades y tu Recruit Score", desc: "Las universidades donde tenés chances reales, y por qué.", done: hasProfile && favCount > 0, goto: hasProfile ? "results" : "form", cta: "Ver mis resultados →", locked: !hasProfile },
    { id: "list", n: 3, title: "Guardá tu lista corta", desc: "Marcá ★ las que te interesan y compáralas.", done: favCount > 0, goto: "mylist", cta: "Ver mi lista →", locked: !hasProfile },
    { id: "eligibility", n: 4, title: "Chequeá tu elegibilidad", desc: "Qué documentos y notas te pide la NCAA/NAIA.", done: eligDone, goto: "eligibility", cta: "Ver requisitos →" },
    { id: "outreach", n: 5, title: "Escribile a un coach", desc: "Un mail con datos reales de esa universidad, desde tu cuenta.", done: outreachCount > 0, goto: hasProfile ? "form" : "form", cta: "Generar mi primer email →", locked: !hasProfile },
  ];

  const doneCount = steps.filter((s) => s.done).length;
  const pct = Math.round((doneCount / steps.length) * 100);
  const allDone = doneCount === steps.length;

  if (dismissed) return null;

  return (
    <div className="rm-section" style={{ borderTop: "none", paddingTop: 30 }}>
      <div className="rm-wrap">
        <div className="rm-onboard">
          <div className="rm-onboard-head">
            <div>
              <h2 className="rm-condensed" style={{ fontSize: 22, margin: 0 }}>{allDone ? "¡Ya diste todos los primeros pasos! 🎉" : hasProfile ? "Seguí desde donde quedaste" : "Empezá acá — es gratis y no te tenés que registrar"}</h2>
              <p style={{ fontSize: 13.5, color: "var(--ink-soft)", margin: "4px 0 0" }}>{allDone ? "Ahora es cuestión de sumar universidades a tu lista y escribirle a más coaches. Volvé cuando quieras." : "Cinco pasos para arrancar por tu cuenta. Nadie te evalúa ni te rechaza."}</p>
            </div>
            <button className="rm-onboard-dismiss" onClick={() => { setDismissed(true); try { lsSetSynced("rr_onboarding_dismissed", "1"); } catch (e) {} }} title="Ocultar">✕</button>
          </div>

          <div className="rm-onboard-progress">
            <div className="rm-onboard-progress-bar"><div style={{ width: `${pct}%` }} /></div>
            <span>{doneCount}/{steps.length} listo</span>
          </div>

          <div className="rm-onboard-steps">
            {steps.map((s) => (
              <div className={`rm-onboard-step${s.done ? " done" : ""}${s.locked ? " locked" : ""}`} key={s.id}>
                <div className="rm-onboard-check">{s.done ? "✓" : s.n}</div>
                <div className="rm-onboard-body">
                  <h3 className="rm-condensed">{s.title}</h3>
                  <p>{s.desc}</p>
                  {!s.done && (
                    s.locked
                      ? <span className="rm-onboard-locked-note">Primero armá tu perfil ↑</span>
                      : <button className="rm-btn-inline" style={{ fontSize: 13, marginTop: 2 }} onClick={() => { setStage(s.goto); window.scrollTo(0, 0); }}>{s.cta}</button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

