// Consentimiento dentro del formulario de perfil. Obligatorio para guardar: acepta Términos y Privacidad
// y, si es menor, pide nombre, correo y conformidad de la madre, el padre o el tutor.
function consentIsValid(c) {
  if (!c || !c.accepted || !c.ageAnswered) return false;
  if (c.minor) return !!(c.parentOk && c.parentName && String(c.parentName).trim() && /.+@.+\..+/.test(String(c.parentEmail || "")));
  return true;
}
function ConsentFields({ value, onChange }) {
  const c = value || {};
  const [reading, setReading] = useState(null);
  const set = (k, v) => onChange({ ...c, [k]: v });
  return (
    <div className="rm-consent">
      <div className="rm-consent-age" role="radiogroup" aria-label="Edad">
        <span>¿Tenés 18 años o más?</span>
        <label><input type="radio" name="rm-age" checked={c.ageAnswered && !c.minor} onChange={() => onChange({ ...c, ageAnswered: true, minor: false })} /> Sí</label>
        <label><input type="radio" name="rm-age" checked={c.ageAnswered && !!c.minor} onChange={() => onChange({ ...c, ageAnswered: true, minor: true })} /> No, soy menor</label>
      </div>
      {c.minor && (
        <div className="rm-consent-parent">
          <p>Como sos menor, tu madre, padre o tutor tiene que autorizar que uses Smartrecruit y cargues tus datos.</p>
          <div className="rm-grid">
            <div className="rm-field"><label>Nombre del adulto responsable</label><input value={c.parentName || ""} onChange={(e) => set("parentName", e.target.value)} /></div>
            <div className="rm-field"><label>Correo del adulto responsable</label><input type="email" value={c.parentEmail || ""} onChange={(e) => set("parentEmail", e.target.value)} /></div>
          </div>
          <label className="rm-consent-check"><input type="checkbox" checked={!!c.parentOk} onChange={(e) => set("parentOk", e.target.checked)} /> Soy la madre, el padre o el tutor. Autorizo que use Smartrecruit y cargue sus datos deportivos y académicos, y acepto los Términos y la Política de Privacidad en su nombre.</label>
        </div>
      )}
      <label className="rm-consent-check">
        <input type="checkbox" checked={!!c.accepted} onChange={(e) => set("accepted", e.target.checked)} />
        <span>Leí y acepto los <button type="button" className="rm-btn-inline" onClick={(e) => { e.preventDefault(); setReading(reading === "terms" ? null : "terms"); }}>Términos y Condiciones</button> y la <button type="button" className="rm-btn-inline" onClick={(e) => { e.preventDefault(); setReading(reading === "privacy" ? null : "privacy"); }}>Política de Privacidad</button>. Entiendo que Smartrecruit no es un agente, no garantiza becas y no contacta entrenadores por mí.</span>
      </label>
      {reading && (
        <div className="rm-consent-reader">
          <button type="button" className="rm-btn-inline" onClick={() => setReading(null)}>Cerrar ✕</button>
          {reading === "terms" ? <TermsPage /> : <PrivacyPage />}
        </div>
      )}
    </div>
  );
}

function AccountMenu({ session }) {
  const [open, setOpen] = useState(false);
  const [syncPending, setSyncPending] = useState(false);
  useEffect(() => {
    const check = () => { try { setSyncPending(localStorage.getItem("rr_sync_pending") === "1"); } catch (e) {} };
    check();
    const t = setInterval(check, 3000);
    return () => clearInterval(t);
  }, []);
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState(null); // null | "sending" | "sent" | "error"
  const send = async () => {
    if (!email || !email.includes("@")) return;
    setStatus("sending");
    try {
      const { error } = await supabase.auth.signInWithOtp({ email, options: { emailRedirectTo: window.location.origin } });
      setStatus(error ? "error" : "sent");
    } catch (e) { setStatus("error"); }
  };
  const signOut = async () => { await supabase.auth.signOut(); syncUserId = null; window.location.reload(); };

  if (session) {
    return (
      <div className="rm-account">
        <span className="rm-account-email" title={session.user.email}>{session.user.email}</span>
        {syncPending && <span className="rm-account-sync" title="Hay cambios que todavía no se guardaron en la nube. Se reintenta solo.">· guardando…</span>}
        <button className="rm-account-link" onClick={signOut}>Cerrar sesión</button>
      </div>
    );
  }
  return (
    <div className="rm-account">
      {!open ? (
        <button className="rm-sidebar-link" onClick={() => setOpen(true)}>
          <span className="rm-sidebar-icon">🔐</span>
          <span className="rm-sidebar-label">Guardar mi progreso</span>
        </button>
      ) : status === "sent" ? (
        <p className="rm-account-note">Te mandamos un link a {email}. Abrilo desde este mismo dispositivo o desde cualquier otro — tu progreso te va a estar esperando ahí.</p>
      ) : (
        <div className="rm-account-form">
          <input type="email" placeholder="tu@email.com" value={email} onChange={(e) => setEmail(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} />
          <button className="rm-btn-inline" disabled={status === "sending"} onClick={send}>{status === "sending" ? "Enviando…" : "Enviarme el link →"}</button>
          {status === "error" && <p className="rm-account-note" style={{ color: "#b23b3b" }}>No se pudo enviar. Probá de nuevo en un momento.</p>}
          <p className="rm-account-note">Así tu perfil, tu lista y tus mails quedan guardados aunque cambies de compu o de celular. Al crear la cuenta aceptás los Términos y la Política de Privacidad (abajo de todo en cada página).</p>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [stage, setStage] = useState(() => {
    // Direcciones públicas de las páginas legales (las pide Google para verificar la app).
    try { const p = window.location.pathname.replace(/\/+$/, ""); if (p === "/privacidad") return "privacy"; if (p === "/terminos") return "terms"; } catch (e) {}
    return "landing";
  });
  const [dataVersion, setDataVersion] = useState(0);
  const [dataAsOf, setDataAsOf] = useState(null);
  useEffect(() => {
    if (typeof fetch !== "function") return undefined; // navegadores sin fetch: se usan los datos embebidos
    let cancelled = false;
    try {
      fetch("/data/live.json", { cache: "no-cache" })
        .then((r) => (r.ok ? r.json() : null))
        .then((live) => { if (!cancelled && applyLiveData(live)) { setDataAsOf(live.generatedAt || null); setDataVersion((v) => v + 1); } })
        .catch(() => {});
    } catch (e) { /* sin datos vivos: se usan los embebidos */ }
    return () => { cancelled = true; };
  }, []);
  const [profile, setProfile] = useState(() => {
    try { const p = JSON.parse(localStorage.getItem("rr_profile") || "null"); return p; } catch (e) { return null; }
  });
  const saveProfile = (p) => {
    const normalized = normalizeProfile(p);
    setProfile(normalized);
    writeJSON("rr_profile", normalized);
  };
  const [selectedSchool, setSelectedSchool] = useState(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const openSchool = (name) => { setSelectedSchool(name); setStage("school"); window.scrollTo(0, 0); };

  // ---- Sesión (Supabase): magic link por email, con migración automática del progreso guardado en este navegador ----
  const [session, setSession] = useState(null);
  useEffect(() => {
    let mounted = true;
    supabase.auth.getSession().then(({ data }) => { if (mounted) setSession(data.session); });
    const { data: sub } = supabase.auth.onAuthStateChange(async (event, sess) => {
      if (!mounted) return;
      setSession(sess);
      syncUserId = sess ? sess.user.id : null;
      if (event === "SIGNED_IN" && sess) {
        const hadRemote = await pullFromCloud(sess.user.id);
        if (!hadRemote) await pushInitialSnapshot(sess.user.id); // primera vez de esta cuenta: sube lo que ya había en este navegador
        window.location.reload(); // recarga simple: todo el sitio lee su estado inicial de localStorage, así queda consistente en un solo lugar
      }
    });
    return () => { mounted = false; sub.subscription.unsubscribe(); };
  }, []);


  const NAV_LINKS = [
    { id: "landing", label: "Inicio", icon: "🏠" },
    { id: "catalog", label: "Universidades", icon: "🎓" },
    { id: "needs", label: "Recruiting Needs", icon: "📋" },
    { id: "calendar", label: "Calendario", icon: "📅" },
    {
      id: "resources", label: "Recursos", icon: "📚",
      children: [
        { id: "eligibility", label: "Elegibilidad", icon: "✅" },
        { id: "video", label: "Tu video", icon: "🎬" },
        { id: "money", label: "Becas y costos", icon: "💵" },
        { id: "exams", label: "Exámenes", icon: "📝" },
        { id: "gpa", label: "Conversor GPA", icon: "🔢" },
        { id: "careers", label: "Buscar por carrera", icon: "🎯" },
      ],
    },
  ];
  // Recursos se despliega hacia abajo. Se abre solo cuando se llega a Recursos o a cualquiera de sus
  // secciones (por ejemplo desde un paso de "Empezá acá"), y se puede cerrar a mano sin cambiar de página.
  const RESOURCE_STAGES = ["resources", "eligibility", "exams", "gpa", "careers"];
  const [resourcesOpen, setResourcesOpen] = useState(false);
  useEffect(() => { if (RESOURCE_STAGES.includes(stage)) setResourcesOpen(true); }, [stage]);
  const toggleResources = () => {
    if (resourcesOpen) { setResourcesOpen(false); return; }
    setResourcesOpen(true);
    if (!RESOURCE_STAGES.includes(stage)) { setStage("resources"); window.scrollTo(0, 0); }
    // el menú móvil queda abierto: la persona todavía tiene que elegir una sección
  };

  return (
    <div className={`rm-root rm-has-sidebar ${sidebarCollapsed ? "sidebar-collapsed" : ""} ${menuOpen ? "sidebar-mobile-open" : ""}`}>
      <style>{CSS}</style>
      <div className="rm-bg-blur" style={{ backgroundImage: `url(${BG_SPORTS_IMAGE})` }} />

      {/* Sidebar lateral izquierdo */}
      <aside className="rm-sidebar">
        <div className="rm-sidebar-top">
          <div className="rm-sidebar-logo" onClick={() => { setStage("landing"); setMenuOpen(false); }}>
            <img src={LOGO_DATA_URI} alt="Smart Recruit" />
            <span className="rm-sidebar-brand">Smartrecruit</span>
          </div>
          <button className="rm-sidebar-toggle" onClick={() => setSidebarCollapsed(!sidebarCollapsed)} aria-label="Expandir/comprimir menú" title="Expandir/comprimir">
            {sidebarCollapsed ? "»" : "«"}
          </button>
        </div>
        <nav className="rm-sidebar-nav">
          {NAV_LINKS.map((l) => l.children ? (
            <React.Fragment key={l.id}>
              <button
                className={`rm-sidebar-link ${stage === l.id ? "active" : ""} ${l.children.some((c) => c.id === stage) ? "has-active" : ""}`}
                onClick={toggleResources}
                aria-expanded={resourcesOpen}
                aria-controls="rm-nav-resources"
                title={l.label}
              >
                <span className="rm-sidebar-icon">{l.icon}</span>
                <span className="rm-sidebar-label">{l.label}</span>
                <svg className={`rm-sidebar-chevron ${resourcesOpen ? "open" : ""}`} width="12" height="12" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M5 7.5l5 5 5-5" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" /></svg>
              </button>
              <div id="rm-nav-resources" className={`rm-nav-sub ${resourcesOpen ? "open" : ""}`} role="group" aria-label={l.label}>
                <div className="rm-nav-sub-inner">
                  {l.children.map((c) => (
                    <button
                      key={c.id}
                      className={`rm-sidebar-link sub ${stage === c.id ? "active" : ""}`}
                      onClick={() => { setStage(c.id); window.scrollTo(0, 0); setMenuOpen(false); }}
                      title={c.label}
                    >
                      <span className="rm-sidebar-icon">{c.icon}</span>
                      <span className="rm-sidebar-label">{c.label}</span>
                    </button>
                  ))}
                </div>
              </div>
            </React.Fragment>
          ) : (
            <button
              key={l.id}
              className={`rm-sidebar-link ${stage === l.id ? "active" : ""}`}
              onClick={() => { setStage(l.id); window.scrollTo(0, 0); setMenuOpen(false); }}
              title={l.label}
            >
              <span className="rm-sidebar-icon">{l.icon}</span>
              <span className="rm-sidebar-label">{l.label}</span>
            </button>
          ))}
        </nav>
        <div className="rm-sidebar-foot">
          <AccountMenu session={session} />
          <button
            className={`rm-sidebar-link ${stage === "profile" ? "active" : ""}`}
            onClick={() => { setStage("profile"); window.scrollTo(0, 0); setMenuOpen(false); }}
            title="Mi perfil"
          >
            <span className="rm-sidebar-icon">👤</span>
            <span className="rm-sidebar-label">Mi perfil</span>
          </button>
        </div>
      </aside>

      {/* Overlay para cerrar el sidebar en mobile */}
      <div className="rm-sidebar-overlay" onClick={() => setMenuOpen(false)} />

      <div className="rm-main">
        {/* Topbar mínimo: hamburguesa (mobile) + ticker */}
        <div className="rm-topbar">
          <button className="rm-topbar-burger" onClick={() => setMenuOpen(!menuOpen)} aria-label="Menú">☰</button>
          <div className="rm-ticker">
            <span className="rm-live-dot"><span></span>EN VIVO</span>
            <div className="rm-ticker-viewport">
              <div className="rm-ticker-track">
                {[...NCAA_POINTS_LEADERS.slice(0, 12), ...NCAA_POINTS_LEADERS.slice(0, 12)].map((p, i) => (
                  <span className="rm-ticker-item" key={i}>#{p.rank} {p.player} ({p.school_short}) — {p.pts} PTS</span>
                ))}
              </div>
            </div>
          </div>
        </div>

      <React.Fragment key={dataVersion}>
      {profile && !(profile.consent && profile.consent.version === LEGAL_VERSION && consentIsValid(profile.consent)) && !["form", "terms", "privacy", "about"].includes(stage) && (
        <div className="rm-wrap" style={{ paddingTop: 16 }}>
          <div className="rm-alert">
            <b>Sumamos Términos y Condiciones y Política de Privacidad.</b> Para seguir usando tu perfil, revisalos y aceptalos
            {" "}(si sos menor de 18, con la conformidad de tu madre, padre o tutor). <button type="button" className="rm-btn-inline" onClick={() => { setStage("form"); window.scrollTo(0, 0); }}>Revisar y aceptar →</button>
          </div>
        </div>
      )}
      {stage === "landing" && (
        <>
          {profile ? (
            <DailyPanel profile={profile} setStage={(st) => { setStage(st); window.scrollTo(0, 0); }} saveProfile={saveProfile} dataAsOf={dataAsOf} />
          ) : (
          <div className="rm-hero">
            <div className="rm-wrap rm-hero-inner">
              <h1 className="rm-condensed">Conseguí tu beca <span>por tu propia cuenta</span>, con datos reales.</h1>
              <p>Te mostramos qué universidades buscan tu posición y con cuáles tenés más chances.</p>
              <button className="rm-btn" onClick={() => setStage("form")}>Armar mi perfil →</button>
            </div>
          </div>
          )}

          <OnboardingPanel profile={profile} setStage={setStage} />
          <OpportunitiesBoard profile={profile} />
        </>
      )}

      {stage === "roadmap" && <RoadmapPage profile={profile} setStage={setStage} />}
      {stage === "outreach" && <MailPage profile={profile} setStage={setStage} />}
      {stage === "mylist" && <MyListPage setStage={setStage} onOpenSchool={openSchool} />}
      {stage === "catalog" && <CatalogPage onOpenSchool={openSchool} />}
      {stage === "school" && selectedSchool && <SchoolProfilePage school={selectedSchool} onBack={() => setStage("catalog")} profileMajor={profile?.major} />}
      {stage === "needs" && <RecruitingNeedsPage />}
      {stage === "eligibility" && <EligibilityPage />}
      {stage === "video" && <VideoGuidePage />}
      {stage === "money" && <MoneyGuidePage />}
      {stage === "calendar" && <CalendarPage />}
      {stage === "exams" && <ExamsPage setStage={setStage} />}
      {stage === "gpa" && <GpaCalculatorPage />}
      {stage === "careers" && <CareerFinderPage profile={profile} onOpenSchool={openSchool} />}
      {stage === "resources" && <ResourcesPage />}
      {stage === "form" && <ProfileForm initial={profile} onSubmit={(p) => { saveProfile(p); setStage("results"); window.scrollTo(0, 0); }} />}
      {stage === "profile" && (profile ? <ProfilePage profile={profile} setStage={setStage} onOpenSchool={openSchool} /> : <ProfileForm onSubmit={(p) => { saveProfile(p); setStage("profile"); window.scrollTo(0, 0); }} />)}
      {stage === "results" && profile && <Results profile={profile} onBack={() => setStage("profile")} onOpenSchool={openSchool} />}
      {stage === "terms" && <TermsPage />}
      {stage === "privacy" && <PrivacyPage />}
      {stage === "about" && <AboutPage setStage={setStage} />}
      <LegalFooter setStage={setStage} />
      </React.Fragment>
      </div>
    </div>
  );
}

function normalizeProfile(p) {
  const gpa4 = GPA_SCALES[p.gpaScale].convert(parseFloat(p.gpaRaw));
  return { ...p, gpa4: Math.round(gpa4 * 100) / 100 };
}
